static size_t cases = 0, exact_values = 0;
static void require(bool ok, const char* text) {
    if (!ok) throw std::runtime_error(text);
}
static void exact(const std::vector<float>& a, const std::vector<float>& b) {
    require(a.size() == b.size() && !std::memcmp(a.data(), b.data(), a.size() * sizeof(float)), "different model outputs");
    for (float value : b) require(std::isfinite(value), "nonfinite model output");
    exact_values += a.size();
}
static void record(const char* name) {
    ++cases;
    std::cout << "{\"case\":\"" << name << "\",\"status\":\"pass\"}\n";
}
struct BodyError { int value; };

struct ObservedCpu : backend::CpuBackend {
    int entries = 0, bodies = 0, matmuls_inside = 0;
    bool inside = false, passthrough = false;
    void run_prefill(const std::function<void()>& work) override {
        ++entries;
        auto body = [&] {
            ++bodies;
            inside = true;
            try { work(); }
            catch (...) { inside = false; throw; }
            inside = false;
        };
        if (passthrough) backend::Backend::run_prefill(std::ref(body));
        else backend::CpuBackend::run_prefill(std::ref(body));
    }
    void matmul(uint32_t type, const uint8_t* data, const float* x, float* y,
                size_t nin, size_t nout, size_t nbatch) override {
        if (inside) ++matmuls_inside;
        backend::CpuBackend::matmul(type, data, x, y, nin, nout, nbatch);
    }
};

int main(int argc, char** argv) {
    try {
        backend::CpuBackend cpu;
        cpu.set_threads(6);
        const auto caller = std::this_thread::get_id();
        int calls = 0;
        bool returned = false;
        cpu.backend::Backend::run_prefill([&] {
            require(!returned && std::this_thread::get_id() == caller, "default callback not synchronous on caller");
            ++calls;
        });
        returned = true;
        require(calls == 1, "default callback count");
        bool caught = false;
        try { cpu.backend::Backend::run_prefill([] { throw BodyError{17}; }); }
        catch (const BodyError& e) { caught = e.value == 17; }
        require(caught, "default callback exception payload");
        record("default-backend-pass-through");

        for (bool enabled : {false, true}) {
            cpu.set_prefill_placement(enabled);
            for (int threads : {1, 6, 4, 6}) {
                cpu.set_threads(threads);
                std::vector<std::thread::id> before(size_t(threads), caller), after(size_t(threads), caller);
                cpu.run_parallel([&](int w) { before[size_t(w)] = std::this_thread::get_id(); });
                calls = 0;
                cpu.run_prefill([&] {
                    ++calls;
                    require(std::this_thread::get_id() == caller, "callback changed caller");
                    std::atomic<int> tasks{0};
                    cpu.parallel_for(37, [&](int) { ++tasks; });
                    require(tasks == 37, "callback primitive did not complete");
                    cpu.set_threads(threads);
                    if (threads == 1) cpu.set_threads(0);
                    bool nested = false, changed = false;
                    int inner_calls = 0;
                    try { cpu.run_prefill([&] { ++inner_calls; }); }
                    catch (const std::exception&) { nested = true; }
                    try { cpu.set_threads(threads == 6 ? 4 : 6); }
                    catch (const std::exception&) { changed = true; }
                    require(nested && inner_calls == 0, "nested scope accepted");
                    require(changed && cpu.threads_available() == threads, "active pool reconfiguration accepted");
                    cpu.run_parallel([&](int w) { after[size_t(w)] = std::this_thread::get_id(); });
                });
                require(calls == 1 && before == after, "callback count or stable pool identities");
                caught = false;
                try { cpu.run_prefill([] { throw BodyError{31}; }); }
                catch (const BodyError& e) { caught = e.value == 31; }
                require(caught, "body error payload lost without cleanup failure");
                calls = 0;
                cpu.run_prefill([&] { ++calls; });
                require(calls == 1, "scope not reusable after successful cleanup");
                record(enabled ? "enabled-contract-and-reconfiguration" : "disabled-contract-and-reconfiguration");
            }
        }

        require(argc == 3, "usage: contract TIED_SMALL_GGUF UNTIED_SMALL_GGUF");
        for (int fixture = 1; fixture < argc; ++fixture) {
            auto weights = gguf::read_gguf(argv[fixture]);
            auto candidate = std::make_shared<ObservedCpu>();
            auto reference = std::make_shared<ObservedCpu>();
            candidate->set_prefill_placement(true);
            reference->passthrough = true;
            infer::Model model(weights, candidate), control(weights, reference);
            model.set_threads(6); control.set_threads(6);
            model.set_ubatch(2); control.set_ubatch(2);
            caught = false;
            try { model.prefill({}); }
            catch (const std::exception&) { caught = true; }
            require(caught && candidate->entries == 0 && model.n_tokens() == 0, "empty prompt entered callback or changed state");
            record("empty-model-prefill-before-scope");
            for (const std::vector<uint32_t>& prompt : {std::vector<uint32_t>{1}, {1, 2, 3}, {1, 2, 3, 4, 5, 6, 7}}) {
                model.reset(); control.reset();
                int entries = candidate->entries, bodies = candidate->bodies, primitives = candidate->matmuls_inside;
                exact(control.prefill(prompt), model.prefill(prompt));
                require(candidate->entries == entries + 1 && candidate->bodies == bodies + 1 && candidate->matmuls_inside > primitives, "model graph not inside one callback");
                require(model.n_tokens() == int(prompt.size()), "model token count");
                exact(control.prefill({8}), model.prefill({8}));
                entries = candidate->entries;
                exact(control.step(9), model.step(9));
                require(candidate->entries == entries, "decode unexpectedly entered prefill callback");
                record("tiny-model-prefill-followup-and-decode");
            }
        }
        std::cout << "{\"status\":\"pass\",\"cases\":" << cases << ",\"exact_values\":" << exact_values << "}\n";
    } catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 1; }
}

