namespace hooks {
const auto real_set = &SetThreadAffinityMask;
const auto real_thread = &GetThreadGroupAffinity;
const auto real_process = &GetProcessAffinityMask;
const auto real_topology = &GetLogicalProcessorInformationEx;
const auto real_groups = &GetActiveProcessorGroupCount;
enum Mode { Normal, MultiGroup, TopologyFail, ProcessFail, SetupThrow,
            QueryOneFail, ApplyOneFail, RestoreOnce, RestoreAlways, RestoreQueryFail };
std::atomic<int> mode{Normal}, applies{0}, restores{0}, apply_ok{0}, restore_ok{0};
std::atomic<int> failed_restores{0};
thread_local int worker = -1, restore_failures = 0;
thread_local DWORD_PTR old = 0;
thread_local bool active = false, just_restored = false;
std::mutex event_mutex;
std::vector<std::string> events;
WORD WINAPI group_count() { return mode == MultiGroup ? 2 : real_groups(); }
BOOL WINAPI process_mask(HANDLE h, PDWORD_PTR a, PDWORD_PTR s) {
    if (mode == ProcessFail) { SetLastError(ERROR_ACCESS_DENIED); return FALSE; }
    return real_process(h, a, s);
}
BOOL WINAPI topology_info(LOGICAL_PROCESSOR_RELATIONSHIP kind,
                         PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX data, PDWORD bytes) {
    if (mode == SetupThrow) throw std::bad_alloc();
    if (mode == TopologyFail) { SetLastError(ERROR_NOT_SUPPORTED); return FALSE; }
    return real_topology(kind, data, bytes);
}
BOOL WINAPI thread_mask(HANDLE h, PGROUP_AFFINITY a) {
    if ((mode == QueryOneFail && worker == 3) || (mode == RestoreQueryFail && just_restored)) {
        SetLastError(ERROR_ACCESS_DENIED); return FALSE;
    }
    return real_thread(h, a);
}
DWORD_PTR WINAPI set_mask(HANDLE h, DWORD_PTR target) {
    const bool restoring = active && target == old;
    if (restoring) ++restores; else ++applies;
    const bool fail = restoring ? (mode == RestoreAlways ||
        (mode == RestoreOnce && restore_failures++ == 0)) : (mode == ApplyOneFail && worker == 3);
    GROUP_AFFINITY before{};
    if (!real_thread(h, &before)) throw std::runtime_error("test raw mask read failed");
    DWORD_PTR result = 0;
    if (fail) { if (restoring) ++failed_restores; SetLastError(ERROR_ACCESS_DENIED); }
    else result = real_set(h, target);
    if (result) {
        if (restoring) { ++restore_ok; active = false; just_restored = true; }
        else { ++apply_ok; old = result; active = true; just_restored = false; }
    }
    std::ostringstream e;
    e << "{\"worker\":" << worker << ",\"thread\":" << GetCurrentThreadId()
      << ",\"restore\":" << (restoring ? "true" : "false")
      << ",\"before\":" << before.Mask << ",\"requested\":" << target
      << ",\"returned\":" << result << ",\"injected\":" << (fail ? "true" : "false") << '}';
    { std::lock_guard<std::mutex> lock(event_mutex); events.push_back(e.str()); }
    return result;
}
void reset_thread(int id) { worker = id; old = 0; active = false; just_restored = false; restore_failures = 0; }
}
#define GetActiveProcessorGroupCount hooks::group_count
#define GetProcessAffinityMask hooks::process_mask
#define GetLogicalProcessorInformationEx hooks::topology_info
#define GetThreadGroupAffinity hooks::thread_mask
#define SetThreadAffinityMask hooks::set_mask
#include "backends/cpu/cpu_backend.hpp"
#undef GetActiveProcessorGroupCount
#undef GetProcessAffinityMask
#undef GetLogicalProcessorInformationEx
#undef GetThreadGroupAffinity
#undef SetThreadAffinityMask

static size_t cases = 0, exact_values = 0;
static void require(bool ok, const char* text) { if (!ok) throw std::runtime_error(text); }
using Masks = std::vector<DWORD_PTR>;
static Masks masks(backend::CpuBackend& cpu) {
    Masks result(size_t(cpu.threads_available()));
    cpu.run_parallel([&](int w) {
        GROUP_AFFINITY a{};
        require(hooks::real_thread(GetCurrentThread(), &a) && a.Group == 0, "raw thread query");
        result[size_t(w)] = a.Mask;
    });
    return result;
}
static void reset(backend::CpuBackend& cpu, hooks::Mode mode) {
    cpu.run_parallel([](int w) { hooks::reset_thread(w); });
    hooks::mode = mode;
    hooks::applies = 0; hooks::restores = 0; hooks::apply_ok = 0;
    hooks::restore_ok = 0; hooks::failed_restores = 0; hooks::events.clear();
}
static void rescue(backend::CpuBackend& cpu, const Masks& original) {
    hooks::mode = hooks::Normal;
    cpu.run_parallel([&](int w) {
        require(hooks::real_set(GetCurrentThread(), original[size_t(w)]) != 0, "manual rescue failed");
        hooks::reset_thread(w);
    });
    require(masks(cpu) == original, "manual rescue mask mismatch");
}
static void record(const std::string& name) {
    ++cases;
    std::cout << "{\"case\":\"" << name << "\",\"status\":\"pass\",\"apply_calls\":" << hooks::applies
      << ",\"restore_calls\":" << hooks::restores << ",\"apply_ok\":" << hooks::apply_ok
      << ",\"restore_ok\":" << hooks::restore_ok << ",\"events\":[";
    for (size_t i = 0; i < hooks::events.size(); ++i) { if (i) std::cout << ','; std::cout << hooks::events[i]; }
    std::cout << "]}\n";
}
static void exact(const std::vector<float>& a, const std::vector<float>& b) {
    require(a.size() == b.size() && !std::memcmp(a.data(), b.data(), a.size() * sizeof(float)), "matrix output differs");
    exact_values += a.size();
}
struct Matrix {
    size_t n = 64, rows = 49, batch = 3;
    std::vector<float> weights, x;
    std::vector<uint8_t> q8;
    Matrix() : weights(rows * n), x(batch * n), q8(rows * 2 * 34) {
        for (size_t i = 0; i < weights.size(); ++i) weights[i] = float(int(i * 13 % 53) - 26) / 31.0f;
        for (size_t i = 0; i < rows; ++i) quant::quantize_row_q8_0(weights.data() + i * n, q8.data() + i * 68, 2);
        input(1);
    }
    void input(int seed) { for (size_t i = 0; i < x.size(); ++i) x[i] = float((int(i) * 7 + seed * 11) % 37 - 18) / float(seed + 19); }
    std::vector<float> run(backend::CpuBackend& cpu, bool f32) {
        std::vector<float> y(rows * batch + 2, 123456.0f);
        cpu.matmul(f32 ? gguf::GGML_TYPE_F32 : gguf::GGML_TYPE_Q8_0,
            f32 ? reinterpret_cast<const uint8_t*>(weights.data()) : q8.data(),
            x.data(), y.data() + 1, n, rows, batch);
        require(y.front() == 123456.0f && y.back() == 123456.0f, "output guards changed");
        for (size_t i = 1; i + 1 < y.size(); ++i) require(std::isfinite(y[i]), "nonfinite output");
        return {y.begin() + 1, y.end() - 1};
    }
};
struct BodyError { int worker; };

int main() {
    try {
        quant::register_builtins();
        backend::CpuBackend cpu; cpu.set_threads(6); cpu.set_prefill_placement(true);
        const Masks original = masks(cpu); Masks bound;
        reset(cpu, hooks::Normal);
        int calls = 0;
        const DWORD caller = GetCurrentThreadId();
        cpu.run_prefill([&] {
            ++calls; require(GetCurrentThreadId() == caller, "body changed caller");
            bound = masks(cpu); DWORD_PTR seen = 0;
            for (size_t i = 0; i < bound.size(); ++i) {
                require(bound[i] && !(bound[i] & (bound[i] - 1)) && !(seen & bound[i]) &&
                        (bound[i] & original[i]) == bound[i], "body not wholly on distinct allowed singleton masks");
                seen |= bound[i];
            }
        });
        require(calls == 1 && hooks::apply_ok == 6 && hooks::restore_ok == 6 && masks(cpu) == original, "phase transition count/restoration");
        record("whole-phase-six-participants");
        Matrix matrix;
        for (int threads : {1, 6, 4, 6}) for (bool f32 : {false, true}) {
            cpu.set_threads(threads); auto saved = masks(cpu); matrix.input(threads + int(f32));
            const auto reference = matrix.run(cpu, f32);
            reset(cpu, hooks::Normal); calls = 0;
            cpu.run_prefill([&] { ++calls; exact(reference, matrix.run(cpu, f32)); });
            require(calls == 1 && masks(cpu) == saved, "reconfigured phase not restored");
            require(hooks::apply_ok == (threads == 6 ? 6 : 0) && hooks::restore_ok == hooks::apply_ok, "phase eligibility count");
            record(std::string(f32 ? "f32-" : "q8-") + std::to_string(threads));
        }
        const Masks refreshed = masks(cpu);
        for (auto mode : {hooks::MultiGroup, hooks::TopologyFail, hooks::ProcessFail, hooks::QueryOneFail, hooks::ApplyOneFail}) {
            reset(cpu, mode); calls = 0;
            cpu.run_prefill([&] { ++calls; require(masks(cpu) == refreshed && hooks::apply_ok == hooks::restore_ok, "body entered with partial placement"); });
            require(calls == 1 && masks(cpu) == refreshed, "fallback did not preserve original masks");
            if (mode == hooks::ApplyOneFail) require(hooks::apply_ok > 0, "partial-apply failure path not exercised");
            record("clean-fallback-" + std::to_string(mode));
        }
        reset(cpu, hooks::Normal);
        const DWORD_PTR restricted = refreshed[0] & ~bound[0];
        require(restricted && hooks::real_set(GetCurrentThread(), restricted), "restrict caller failed");
        const Masks custom = masks(cpu); calls = 0;
        cpu.run_prefill([&] { ++calls; require(masks(cpu) == custom, "restricted participant caused partial/widened placement"); });
        require(calls == 1 && masks(cpu) == custom && hooks::apply_ok == hooks::restore_ok, "restricted fallback cleanup");
        require(hooks::real_set(GetCurrentThread(), refreshed[0]), "restore test caller restriction");
        record("restricted-mask-all-or-clean-fallback");

        reset(cpu, hooks::SetupThrow); calls = 0; bool caught = false;
        try { cpu.run_prefill([&] { ++calls; }); } catch (const std::bad_alloc&) { caught = true; }
        require(caught && !calls && !hooks::apply_ok && masks(cpu) == refreshed, "setup failure mutated or invoked body");
        record("setup-throw-before-mutation");
        for (int failing : {-1, 0, 3}) {
            reset(cpu, hooks::Normal); calls = 0; caught = false; std::atomic<int> finished{0};
            try { cpu.run_prefill([&] {
                ++calls;
                if (failing == -1) throw BodyError{-1};
                cpu.run_parallel([&](int w) { ++finished; if (w == failing) throw BodyError{w}; });
            }); } catch (const BodyError& e) { caught = e.worker == failing; }
            require(caught && calls == 1 && masks(cpu) == refreshed && hooks::apply_ok == hooks::restore_ok, "body exception cleanup");
            if (failing != -1) require(finished == 6, "body task escaped before all workers finished");
            record("body-error-" + std::to_string(failing));
        }
        for (auto mode : {hooks::RestoreOnce, hooks::RestoreAlways, hooks::RestoreQueryFail}) {
            reset(cpu, mode); calls = 0; caught = false;
            try { cpu.run_prefill([&] { ++calls; }); }
            catch (const std::exception& e) { caught = std::string(e.what()).find("restore") != std::string::npos; }
            require(caught && calls == 1, "cleanup failure hidden");
            if (mode == hooks::RestoreAlways) {
                require(masks(cpu) != refreshed && hooks::failed_restores >= 6, "persistent refusal falsely recovered");
                rescue(cpu, refreshed);
            } else require(masks(cpu) == refreshed, "recoverable cleanup not restored");
            record("restore-error-" + std::to_string(mode));
            reset(cpu, hooks::Normal); calls = 0;
            cpu.run_prefill([&] { ++calls; });
            require(calls == 1 && masks(cpu) == refreshed, "reuse after verified restoration/test rescue");
            record("reuse-after-verified-restore-or-test-rescue");
        }
        reset(cpu, hooks::RestoreOnce); caught = false;
        try { cpu.run_prefill([] { throw BodyError{-1}; }); }
        catch (const std::exception& e) { caught = std::string(e.what()).find("restore") != std::string::npos; }
        require(caught && masks(cpu) == refreshed, "cleanup error precedence or retry");
        record("dual-body-and-cleanup-failure");
        reset(cpu, hooks::Normal); calls = 0; cpu.run_prefill([&] { ++calls; });
        require(calls == 1 && masks(cpu) == refreshed, "final scope reuse");
        record("final-reuse");
        std::cout << "{\"status\":\"pass\",\"cases\":" << cases << ",\"exact_values\":" << exact_values
                  << ",\"persistent_failure_cleanup\":\"manual test rescue only\"}\n";
    } catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 1; }
}

#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <new>
#include <stdexcept>
#include <thread>
#include "backends/cpu/cpu_backend.hpp"

static std::atomic<int> fail_allocation{-1};

void* operator new(std::size_t size) {
    if (fail_allocation.load() >= 0 && fail_allocation.fetch_sub(1) == 0) {
        fail_allocation.store(-1);
        throw std::bad_alloc();
    }
    if (void* p = std::malloc(size ? size : 1)) return p;
    throw std::bad_alloc();
}
#if defined(__GNUC__)
// Keep GCC's allocation-pair warning from inlining through this test allocator.
__attribute__((noinline))
#endif
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { ::operator delete(p); }

struct AllocationFailure {
    explicit AllocationFailure(int after) { fail_allocation.store(after); }
    ~AllocationFailure() { fail_allocation.store(-1); }
};

struct Failure { int worker; };

static void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}

static void check_dispatch(backend::CpuBackend& cpu, int threads, int failing) {
    std::atomic<int> entered{0}, finished{0};
    bool caught = false;
    try {
        cpu.run_parallel([&](int worker) {
            entered.fetch_add(1);
            while (entered.load() != threads) std::this_thread::yield();
            if (worker == failing || failing == -1) {
                finished.fetch_add(1);
                throw Failure{worker};
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(2));
            finished.fetch_add(1);
        });
    } catch (const Failure& error) {
        caught = true;
        require(failing == -1 || error.worker == failing, "wrong exception payload");
        require(finished.load() == threads, "exception escaped before workers finished");
    }
    require(caught, "task exception was swallowed");
    std::atomic<int> calls{0};
    cpu.parallel_for(37, [&](int) { calls.fetch_add(1); });
    require(calls.load() == 37, "pool not reusable after exception");
}

static void check_startup() {
    bool success = false;
    int constructor_failures = 0, resize_failures = 0;
    for (int after = 0; after < 128 && !success; ++after) {
        try {
            AllocationFailure fail(after);
            backend::CpuBackend cpu;
            success = true;
        } catch (const std::bad_alloc&) { ++constructor_failures; }
    }
    require(success && constructor_failures > 1, "constructor fault sweep incomplete");
    backend::CpuBackend cpu;
    success = false;
    for (int after = 0; after < 128 && !success; ++after) {
        cpu.set_threads(1);
        try {
            AllocationFailure fail(after);
            cpu.set_threads(4);
            success = true;
        } catch (const std::bad_alloc&) {
            ++resize_failures;
            require(cpu.threads_available() == 1, "failed startup did not leave serial backend");
            check_dispatch(cpu, 1, 0);
            cpu.set_threads(4);
            check_dispatch(cpu, 4, 2);
        }
    }
    require(success && resize_failures > 1, "resize fault sweep incomplete");
    std::printf("startup allocation failures: constructor=%d resize=%d\n",
                constructor_failures, resize_failures);
}

int main() {
    try {
        check_startup();
        backend::CpuBackend cpu;
        for (int threads : {1, 2, 4}) {
            cpu.set_threads(threads);
            for (int repeat = 0; repeat < 10; ++repeat)
                for (int failing = -1; failing < threads; ++failing)
                    check_dispatch(cpu, threads, failing);
            bool caught = false;
            try {
                cpu.parallel_for(64, [](int i) { if (i == 63) throw std::bad_alloc(); });
            } catch (const std::bad_alloc&) { caught = true; }
            require(caught, "allocation exception type was lost");
            check_dispatch(cpu, threads, 0);
        }
        std::puts("backend errors: passed");
        return 0;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "%s\n", error.what());
        return 1;
    } catch (...) {
        std::fputs("unexpected exception\n", stderr);
        return 1;
    }
}

#include <array>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include "backends/cpu/cpu_backend.hpp"

static void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

static size_t check_prefill_reduction() {
    size_t count = 0;
    for (size_t n : std::array<size_t, 19>{0,1,2,7,8,9,15,16,17,31,32,33,127,128,129,1023,1024,1025,2048}) {
        for (size_t offset = 0; offset < 8; ++offset) {
            const size_t stride = n + 13;
            std::vector<float> rows(4 * stride + 8), inputs(3 * stride + 8);
            for (size_t i = 0; i < rows.size(); ++i)
                rows[i] = float(int((i * 1471 + 7) % 65521) - 32760) / 317.0f;
            for (size_t i = 0; i < inputs.size(); ++i)
                inputs[i] = float(int((i * 769 + 23) % 32749) - 16374) / 523.0f;
            const float* r = rows.data() + offset;
            const float* x = inputs.data() + offset;
            float actual[12];
            backend::CpuBackend::dot_f32_x4x3(r, stride, x, x + stride, x + 2 * stride, n, actual, actual + 4, actual + 8);
            for (size_t c = 0; c < 3; ++c) for (size_t k = 0; k < 4; ++k) {
                float lanes[8] = {};
                size_t j = 0;
                for (; j + 8 <= n; j += 8)
                    for (size_t lane = 0; lane < 8; ++lane)
                        lanes[lane] = std::fma(r[k * stride + j + lane], x[c * stride + j + lane], lanes[lane]);
                float v = lanes[0];
                for (size_t lane = 1; lane < 8; ++lane) v += lanes[lane];
                for (; j < n; ++j) v += r[k * stride + j] * x[c * stride + j];
                require(std::memcmp(&v, &actual[c * 4 + k], sizeof(float)) == 0,
                        "prefill reduction differs from ordered scalar FMA oracle");
                ++count;
            }
        }
    }
    return count;
}

static size_t check_q8_scales(backend::CpuBackend& cpu) {
    size_t count = 0;
    std::array<uint8_t, 34> row{};
    std::array<float, 32> x{};
    for (unsigned h = 0; h < 65536; ++h) {
        if ((h & 0x7c00) == 0x7c00) continue;
        row[0] = uint8_t(h);
        row[1] = uint8_t(h >> 8);
        const size_t lane = h % x.size();
        x[lane] = 1.0f;
        for (int q : {-128, -1, 0, 127}) {
            std::fill(row.begin() + 2, row.end(), uint8_t(q));
            // A one-hot input makes every finite f16 scale times int8 exact
            // in f32, independently of the SIMD reduction order.
            const float expected = f16_to_f32(uint16_t(h)) * float(q);
            const float actual = cpu.dot_q8_0(row.data(), x.data(), 1);
            require(std::isfinite(actual) && actual == expected, "Q8 scale or signed weight differs");
            ++count;
        }
        x[lane] = 0.0f;
    }
    return count;
}

struct Matrix {
    uint32_t type;
    size_t rows;
    std::vector<float> weights;
    std::vector<uint8_t> packed;
    std::vector<float> separate, grouped;

    const uint8_t* data() const {
        return type == gguf::GGML_TYPE_F32
            ? reinterpret_cast<const uint8_t*>(weights.data()) : packed.data();
    }

    Matrix(uint32_t t, size_t n, size_t width, size_t batch) : type(t), rows(n) {
        weights.resize(rows * width);
        for (size_t i = 0; i < weights.size(); ++i)
            weights[i] = float(int((i * 37 + 13) % 257) - 128) / 128.0f;
        if (type != gguf::GGML_TYPE_F32) {
            const auto* q = quant::Registry::instance().get(type);
            const size_t blocks = weights.size() / q->block_size;
            packed.resize(blocks * q->type_size);
            if (q->quantize) q->quantize(weights.data(), packed.data(), blocks);
            else {
                for (size_t i = 0; i < packed.size(); ++i)
                    packed[i] = uint8_t(i * 73 + 19);
                for (size_t b = 0; b < blocks; ++b) {
                    uint8_t* p = packed.data() + b * q->type_size;
                    // Finite binary-power scales, including f16 subnormals.
                    const uint16_t scale = b % 3 == 0 ? 1 : 0x2000;
                    const size_t offset = type == gguf::GGML_TYPE_Q6_K ? 208 : 0;
                    std::memcpy(p + offset, &scale, sizeof(scale));
                    if (type != gguf::GGML_TYPE_Q6_K)
                        std::memcpy(p + 2, &scale, sizeof(scale));
                }
            }
            q->dequantize(packed.data(), weights.data(), blocks);
        }
        separate.assign(rows * batch + 2, 123456.0f);
        grouped = separate;
    }

    backend::Projection projection() {
        return {type, data(), grouped.data() + 1, rows};
    }
};

static size_t check(backend::CpuBackend& cpu, std::array<uint32_t, 3> types,
                    size_t width, size_t rows, size_t batch) {
    std::array<Matrix, 3> matrices = {
        Matrix(types[0], rows, width, batch),
        Matrix(types[1], rows + 2, width, batch),
        Matrix(types[2], rows + 4, width, batch)};
    std::vector<float> x(width * batch);
    for (size_t i = 0; i < x.size(); ++i)
        x[i] = float(int((i * 19 + 7) % 101) - 50) / 32.0f;
    const auto original = x;
    for (auto& m : matrices)
        cpu.matmul(m.type, m.data(), x.data(), m.separate.data() + 1, width, m.rows, batch);
    cpu.matmul_group({matrices[0].projection(), matrices[1].projection(), matrices[2].projection()},
                     x.data(), width, batch);
    require(x == original, "grouped matmul modified activations");
    size_t count = 0;
    for (const auto& m : matrices) {
        require(std::memcmp(m.separate.data(), m.grouped.data(), m.grouped.size() * sizeof(float)) == 0,
                "grouped output differs from separate calls or overwrote a sentinel");
        require(m.grouped.front() == 123456.0f && m.grouped.back() == 123456.0f,
                "output boundary overwritten");
        for (size_t b = 0; b < batch; ++b) {
            for (size_t o = 0; o < m.rows; ++o) {
                double expected = 0, magnitude = 0;
                for (size_t i = 0; i < width; ++i) {
                    const double product = double(m.weights[o * width + i]) * x[b * width + i];
                    expected += product;
                    magnitude += std::abs(product);
                }
                const float actual = m.grouped[1 + b * m.rows + o];
                require(std::isfinite(actual) && std::abs(actual - expected) <= 2e-6 * (1 + magnitude),
                        "output differs from double-precision dot oracle");
                ++count;
            }
        }
    }
    auto& first = matrices[0];
    std::fill(first.grouped.begin() + 1, first.grouped.end() - 1, 123456.0f);
    cpu.matmul_group({first.projection()}, x.data(), width, batch);
    require(first.grouped == first.separate, "single-projection fallback differs");
    return count;
}

int main() {
    try {
        quant::register_builtins();
        backend::CpuBackend cpu;
        cpu.set_threads(1);
        const size_t scales = check_q8_scales(cpu);
        const size_t reductions = check_prefill_reduction();
        size_t values = 0, cases = 0;
        for (int threads : {1, 2, 6}) {
            cpu.set_threads(threads);
            cpu.matmul_group({}, nullptr, 0, 1);
            for (size_t rows : {size_t(7), size_t(47), size_t(48), size_t(65)}) {
                for (size_t batch : {size_t(0), size_t(1), size_t(2), size_t(3), size_t(4)}) {
                    for (uint32_t type : {gguf::GGML_TYPE_F32, gguf::GGML_TYPE_Q8_0,
                            gguf::GGML_TYPE_Q4_0, gguf::GGML_TYPE_Q4_1, gguf::GGML_TYPE_Q4_K,
                            gguf::GGML_TYPE_Q5_K, gguf::GGML_TYPE_Q6_K}) {
                        values += check(cpu, {type, type, type}, type == gguf::GGML_TYPE_F32 ? 37 : 256,
                                        rows, batch);
                        ++cases;
                    }
                    values += check(cpu, {gguf::GGML_TYPE_Q8_0, gguf::GGML_TYPE_F32, gguf::GGML_TYPE_Q4_K},
                                    256, rows, batch);
                    ++cases;
                    values += check(cpu, {gguf::GGML_TYPE_Q8_0, gguf::GGML_TYPE_Q6_K, gguf::GGML_TYPE_Q4_K},
                                    256, rows, batch);
                    ++cases;
                }
            }
        }
        bool rejected = false;
        try { cpu.matmul_group({{9999, nullptr, nullptr, 65}, {9999, nullptr, nullptr, 67}}, nullptr, 256, 1); }
        catch (const std::runtime_error&) { rejected = true; }
        require(rejected, "invalid quant type was not rejected on caller");
        std::cout << "grouped projections: " << cases << " cases, " << values
                  << " outputs checked against separate calls and double dots; "
                  << scales << " exact finite Q8 scale/weight cases; "
                  << reductions << " ordered prefill reductions\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

