static void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}

struct Failure { int value; };

int main() {
    backend::detail::PrefillPlacement placement(true);
    require(!placement.enabled() && !placement.applied() && !placement.needs_restore(),
            "non-Windows helper did not fall back");
    placement.apply(0);
    placement.restore(0);
    backend::CpuBackend cpu;
    const auto caller = std::this_thread::get_id();
    int completed = 0, nested = 0, thread_guards = 0, body_errors = 0;
    for (bool enabled : {false, true}) {
        cpu.set_prefill_placement(enabled);
        for (int count : {1, 6, 4, 6}) {
            cpu.set_threads(count);
            int calls = 0;
            cpu.run_prefill([&] {
                ++calls;
                require(std::this_thread::get_id() == caller, "body moved to worker");
                cpu.set_threads(count);
                if (count == 1) cpu.set_threads(0);
                bool rejected = false;
                try { cpu.set_threads(count == 6 ? 4 : 6); }
                catch (const std::runtime_error&) { rejected = true; }
                require(rejected && cpu.threads_available() == count, "thread mutation accepted");
                ++thread_guards;
                rejected = false;
                try { cpu.run_prefill([&] { ++calls; }); }
                catch (const std::runtime_error&) { rejected = true; }
                require(rejected && calls == 1, "nested callback accepted");
                ++nested;
                std::atomic<int> visits{0};
                cpu.parallel_for(41, [&](int) { ++visits; });
                require(visits == 41, "callback held a pending pool job");
            });
            require(calls == 1, "body count differs from one");
            ++completed;
            try {
                cpu.run_prefill([&] {
                    require(std::this_thread::get_id() == caller, "throwing body moved");
                    throw Failure{17};
                });
                require(false, "body error swallowed");
            } catch (const Failure& error) {
                require(error.value == 17, "body payload changed");
                ++body_errors;
            }
            cpu.set_threads(count == 6 ? 4 : 6);
            cpu.set_threads(count);
            cpu.run_prefill([&] { ++completed; });
        }
        bool empty_rejected = false;
        try { cpu.run_prefill(std::function<void()>{}); }
        catch (const std::bad_function_call&) { empty_rejected = true; }
        require(empty_rejected, "empty callable did not propagate");
        cpu.run_prefill([&] { ++completed; });
    }
    require(completed == 18 && nested == 8 && thread_guards == 8 && body_errors == 8,
            "case count changed");
    std::printf("callback fallback: 18 successful scopes, 8 nested rejections, 8 thread guards, "
                "8 body errors, 2 empty-call errors, caller identity and pool reuse pass\n");
}

