// IEEE 754 binary16 <-> binary32 conversion, from scratch (no libs).

inline uint16_t f32_to_f16(float f) {
    union { uint32_t u; float f; } x;
    x.f = f;
    uint32_t s = (x.u >> 16) & 0x8000u;   // sign bit (bit 15 of half)
    uint32_t e = (x.u >> 23) & 0xffu;     // f32 exponent
    uint32_t m = x.u & 0x7fffffu;         // f32 mantissa

    if (e == 0xffu) {                     // inf / nan
        return (uint16_t)(s | 0x7c00u | (m ? 0x0200u : 0u));
    }

    int es = (int)e - 127 + 15;           // rebias to f16
    if (es >= 31) {                        // overflow -> inf
        return (uint16_t)(s | 0x7c00u);
    }
    if (es <= 0) {                         // subnormal f16
        if (es < -10) {                    // underflow to zero
            return (uint16_t)s;
        }
        // Subnormal half: the result is the full 24-bit significand shifted
        // right by (14 - es), with no implicit leading 1 left in it.
        // The 0xfff round-to-nearest bias that the NORMAL path uses belongs
        // before a pending 13-bit shift; applying it here added 4095 to an
        // already-shifted 10-bit value and produced a normal half roughly
        // 200x too large.
        m |= 0x800000u;                    // restore implicit leading 1
        const uint32_t shift = (uint32_t)(14 - es);   // 14..24
        uint32_t half = m >> shift;
        const uint32_t rem = m & ((1u << shift) - 1u);
        const uint32_t halfway = 1u << (shift - 1);
        if (rem > halfway || (rem == halfway && (half & 1u))) half++;
        return (uint16_t)(s | half);
    }
    uint32_t h = (m >> 13) + ((m & 0x1000u) ? 1u : 0u); // round-to-nearest
    return (uint16_t)(s | ((uint32_t)es << 10) | h);
}

inline float f16_to_f32(uint16_t h) {
    uint32_t sign = (uint32_t)(h & 0x8000u) << 16;
    uint32_t e = (h >> 10) & 0x1fu;
    uint32_t m = h & 0x3ffu;
    uint32_t u;
    if (e == 0) {
        if (m == 0) {
            u = sign;                      // zero
        } else {
            // Subnormal half: value is m * 2^-24, with no implicit leading 1.
            // Shift left until bit 10 becomes that implicit 1; after k shifts
            // the value is (1+frac) * 2^(-14-k), so the f32 exponent field is
            // 113 - k. Incrementing instead of decrementing here made every
            // subnormal 2^(2k) too large -- 16x for the k=2 case that Q6_K
            // super-block scales land in.
            uint32_t k = 0;
            while ((m & 0x400u) == 0) { m <<= 1; k++; }
            m &= 0x3ffu;
            u = sign | ((113u - k) << 23) | (m << 13);
        }
    } else if (e == 0x1fu) {               // inf / nan
        u = sign | 0x7f800000u | (m << 13);
    } else {
        u = sign | ((e + 112) << 23) | (m << 13);
    }
    float f;
    std::memcpy(&f, &u, 4);
    return f;
}

#pragma once
#include <string>
#include <vector>
#include <utility>
#include <stdexcept>
#include <cstdint>
#include <cstdlib>
#include <cctype>

// Minimal recursive-descent JSON parser, written from scratch (no libs).

namespace jmini {

struct Value;
using Object = std::vector<std::pair<std::string, Value>>;
using Array  = std::vector<Value>;

struct Value {
    enum class T { Null, Bool, Number, String, Array, Object } t = T::Null;
    bool b = false;
    double num = 0;
    std::string str;
    Array arr;
    Object obj;

    bool isObject() const { return t == T::Object; }
    bool isArray()  const { return t == T::Array; }
    bool isString() const { return t == T::String; }
    bool isNumber() const { return t == T::Number; }

    const Value* get(const std::string& k) const {
        if (t != T::Object) return nullptr;
        for (const auto& p : obj) if (p.first == k) return &p.second;
        return nullptr;
    }
    const std::string& asString() const { return str; }
    double asNumber() const { return num; }
    const Array& asArray() const { return arr; }
};

class Parser {
    const std::string& s;
    size_t i = 0;

    void ws() { while (i < s.size() && (s[i]==' '||s[i]=='\t'||s[i]=='\n'||s[i]=='\r')) i++; }
    char peek() {
        if (i >= s.size()) throw std::runtime_error("json: unexpected end of input");
        return s[i];
    }
    void expect(char c) { ws(); if (peek() != c) throw std::runtime_error("json: expected character"); i++; }

    std::string parseString() {
        expect('"');
        std::string out;
        while (i < s.size()) {
            char c = s[i++];
            if (c == '"') return out;
            if (c == '\\') {
                char e = s[i++];
                switch (e) {
                    case '"':  out += '"';  break;
                    case '\\': out += '\\'; break;
                    case '/':  out += '/';  break;
                    case 'b':  out += '\b'; break;
                    case 'f':  out += '\f'; break;
                    case 'n':  out += '\n'; break;
                    case 'r':  out += '\r'; break;
                    case 't':  out += '\t'; break;
                    case 'u': {
                        if (i + 4 <= s.size()) {
                            unsigned v = (unsigned)std::strtoul(s.substr(i, 4).c_str(), nullptr, 16);
                            out += (char)v;
                            i += 4;
                        }
                        break;
                    }
                    default: out += e;
                }
            } else out += c;
        }
        throw std::runtime_error("json: unterminated string");
    }

    Value parseObject() {
        Value v; v.t = Value::T::Object;
        expect('{'); ws();
        if (peek() == '}') { i++; return v; }
        for (;;) {
            ws();
            std::string key = parseString();
            ws(); expect(':');
            Value val = parseValue();
            v.obj.push_back({ std::move(key), std::move(val) });
            ws();
            char c = peek();
            if (c == ',') { i++; continue; }
            if (c == '}') { i++; break; }
            throw std::runtime_error("json: object syntax error");
        }
        return v;
    }

    Value parseArray() {
        Value v; v.t = Value::T::Array;
        expect('['); ws();
        if (peek() == ']') { i++; return v; }
        for (;;) {
            Value val = parseValue();
            v.arr.push_back(std::move(val));
            ws();
            char c = peek();
            if (c == ',') { i++; continue; }
            if (c == ']') { i++; break; }
            throw std::runtime_error("json: array syntax error");
        }
        return v;
    }

    Value parseValue() {
        ws();
        char c = peek();
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') { Value v; v.t = Value::T::String; v.str = parseString(); return v; }
        if (c == 't') { expect('t'); expect('r'); expect('u'); expect('e'); Value v; v.t = Value::T::Bool; v.b = true; return v; }
        if (c == 'f') { expect('f'); expect('a'); expect('l'); expect('s'); expect('e'); Value v; v.t = Value::T::Bool; v.b = false; return v; }
        if (c == 'n') { expect('n'); expect('u'); expect('l'); expect('l'); return Value(); }
        std::string num;
        if (c == '-') { num += c; i++; }
        while (i < s.size() && (std::isdigit((unsigned char)s[i]) || s[i]=='.'||s[i]=='e'||s[i]=='E'||s[i]=='+'||s[i]=='-')) num += s[i++];
        Value v; v.t = Value::T::Number; v.num = std::strtod(num.c_str(), nullptr); return v;
    }

public:
    explicit Parser(const std::string& str) : s(str) {}

    Value parse() {
        ws();
        Value v = parseValue();
        ws();
        if (i != s.size()) throw std::runtime_error("json: trailing data after document");
        return v;
    }
};

inline Value parse(const std::string& s) { return Parser(s).parse(); }

} // namespace jmini

#pragma once
#include <cstdint>
