from pathlib import Path
import ast, copy, hashlib, json, math, re, statistics

root = Path(__file__).resolve().parent.parent
source = (root / 'run.py').read_bytes()
plan = json.loads((root / 'plan.json').read_bytes())
tree = ast.parse(source)
body = next(node for node in tree.body if isinstance(node, ast.Try)).body
checks = []

def compiled(nodes):
    return compile(ast.fix_missing_locations(ast.Module(body=copy.deepcopy(nodes), type_ignores=[])), '<selected-runner-ast>', 'exec')

def named_loop(name):
    return next(node for node in body if isinstance(node, ast.For) and isinstance(node.target, ast.Name) and node.target.id == name)

def assigned_pair(name):
    index = next(i for i, node in enumerate(body) if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == name for target in node.targets))
    return body[index:index + 2]

order = copy.deepcopy(named_loop('pair'))
models = next(node for node in order.body if isinstance(node, ast.For))
models.body[0].body = ast.parse("sequence.append((pair,model['name'],arm))").body
context = dict(plan=plan, sequence=[])
exec(compiled([order]), context)
sequence = context['sequence']
orders = {-1: ['prefill','scheduler','production'], 0: ['scheduler','prefill','production'], 1: ['scheduler','production','prefill'], 2: ['production','scheduler','prefill'], 3: ['production','prefill','scheduler'], 4: ['prefill','production','scheduler']}
expected = [(pair, model, arm) for pair in range(-1, 5) for model in (['8b','0.6b'] if pair in [-1,1,3] else ['0.6b','8b']) for arm in orders[pair]]
assert len(sequence) == 36 and sequence == expected
checks.append('exact36row_order_each_workload')
for model in ['0.6b','8b']:
    for arm in plan['arms']:
        assert [item[0] for item in sequence if item[1:] == (model,arm) and item[0] >= 0] == list(range(5))
checks.append('exactly5measured_rows_per_model_arm')
summary_code = compiled(assigned_pair('summary'))
for case in plan['workloads']:
    rows = []
    for pair, model, arm in sequence:
        pp = 100 + pair * 3 + (10 if arm == 'prefill' else 2 if arm == 'scheduler' else 0)
        tg = 40 + pair + (2 if arm == 'prefill' else 1 if arm == 'scheduler' else 0)
        rows.append(dict(pair=pair, model=model, arm=arm, records=[dict(pp_ms=9999,tg_ms=9999), dict(pp_ms=1000*case['pp_tokens']/pp,tg_ms=32000/tg)]))
    context = dict(plan=plan, case=case, state=dict(rows=rows), statistics=statistics)
    exec(summary_code, context)
    assert len(context['summary']) == 4
    for item in context['summary']:
        count = case['pp_tokens'] if item['phase'] == 'pp' else 32
        for arm in plan['arms']:
            values = [1000*count/row['records'][1][item['phase']+'_ms'] for row in rows if row['pair'] >= 0 and row['model'] == item['model'] and row['arm'] == arm]
            assert item[arm]['samples'] == values and len(values) == 5
        for control in ['production','scheduler']:
            assert item['comparisons'][control]['prefill_wins'] == sum(y>x for x,y in zip(item[control]['samples'],item['prefill']['samples']))
    checks.append(case['name']+'_aggregation_second_record_counts_pair_alignment')
    for mutation in ['missing','extra']:
        broken = copy.deepcopy(rows)
        index = next(i for i,row in enumerate(broken) if row['pair'] == 0 and row['arm'] == 'production' and row['model'] == '0.6b')
        if mutation == 'missing': broken.pop(index)
        else: broken.append(copy.deepcopy(broken[index]))
        try: exec(summary_code, dict(plan=plan,case=case,state=dict(rows=broken),statistics=statistics))
        except AssertionError: checks.append(case['name']+'_'+mutation+'_sample_rejected')
        else: raise AssertionError('sample corruption accepted')

def baseline(workload):
    return [dict(model=model,phase=phase,production=dict(mean=100.,median=100.),scheduler=dict(mean=100.,median=100.),prefill=dict(mean=105. if workload=='primary' and phase=='pp' else 99.5,median=105. if workload=='primary' and phase=='pp' else 99.5),comparisons={control:dict(mean_change_percent=100.,median_change_percent=100.,prefill_wins=4) for control in ['production','scheduler']}) for model in ['0.6b','8b'] for phase in ['pp','tg']]

decision = compiled(assigned_pair('advance'))
def accepts(workload, summary):
    context = dict(workload=workload,summary=summary)
    exec(decision, context)
    return bool(context['advance'])

for workload in ['primary','followup1','followup9']:
    base = baseline(workload)
    assert accepts(workload,base)
    checks.append(workload+'_all_exact_equal_boundaries_accepted')
    for index in range(4):
        for control in ['production','scheduler']:
            for kind in ['mean','median']:
                bad = copy.deepcopy(base)
                item = bad[index]
                other = 'scheduler' if control == 'production' else 'production'
                item[other]['mean'] = item[other]['median'] = 90.
                item['prefill'][kind] = math.nextafter(item['prefill'][kind], -math.inf)
                assert not accepts(workload,bad)
                checks.append(f'{workload}_{index}_{control}_{kind}_below_boundary_rejected')
    for index,item in enumerate(base):
        if workload == 'primary' and item['phase'] == 'pp':
            for control in ['production','scheduler']:
                bad = copy.deepcopy(base)
                bad[index]['comparisons'][control]['prefill_wins'] = 3
                assert not accepts(workload,bad)
                checks.append(f'primary_{index}_{control}_3wins_rejected')
        else:
            good = copy.deepcopy(base)
            for control in ['production','scheduler']: good[index]['comparisons'][control]['prefill_wins'] = 0
            assert accepts(workload,good)
            checks.append(f'{workload}_{index}_nonprimary_no_wins_requirement')

prerequisite = named_loop('prerequisite')
identity_code = compiled([node for node in prerequisite.body if isinstance(node,ast.Assert)])
for workload,names in [('primary',[]),('followup1',['primary']),('followup9',['primary','followup1'])]:
    assert eval(compile(ast.Expression(prerequisite.iter),'<prerequisites>','eval'),dict(workload=workload)) == names
    checks.append(workload+'_required_predecessors')
state = {key:'current-'+key for key in ['plan_sha256','runner_sha256','manifest_sha256']}
prior = dict(state,status='pass',screening_advance=True)
exec(identity_code,dict(prior=prior,state=state))
checks.append('matching_prerequisite_accepted')
for field in ['status','screening_advance','plan_sha256','runner_sha256','manifest_sha256']:
    bad = dict(prior)
    bad[field] = False if field == 'screening_advance' else 'bad'
    try: exec(identity_code,dict(prior=bad,state=state))
    except AssertionError: checks.append('prerequisite_'+field+'_mismatch_rejected')
    else: raise AssertionError('prerequisite failure accepted')

witness_code = compiled([node for node in body[:4] if isinstance(node,ast.Assert)] + [named_loop('row')])
witness_base = dict(status='pass',plan_sha256='current-plan',rows=[dict(name=f'{model}-{workload}-{arm}',status='pass',returncode=0,binary_sha256='current-production' if arm=='production' else 'current-witness') for model in ['0.6b','8b'] for workload in ['primary','followup1','followup9'] for arm in ['production','scheduler','prefill']])
def witness_accepts(witness):
    try: exec(witness_code,dict(witness=witness,state=dict(plan_sha256='current-plan'),root=Path('/virtual'),sha=lambda p:'current-production' if p.name=='callback-production.exe' else 'current-witness'))
    except AssertionError: return False
    return True
assert witness_accepts(witness_base)
checks.append('witness_matching18identities_accepted')
for mutation in ['status','plan','row_status','exit','binary_production','binary_witness','missing_row','extra_row']:
    bad = copy.deepcopy(witness_base)
    if mutation == 'status': bad['status']='failed'
    elif mutation == 'plan': bad['plan_sha256']='old-plan'
    elif mutation == 'row_status': bad['rows'][0]['status']='failed'
    elif mutation == 'exit': bad['rows'][0]['returncode']=1
    elif mutation == 'binary_production': bad['rows'][0]['binary_sha256']='old'
    elif mutation == 'binary_witness': bad['rows'][1]['binary_sha256']='old'
    elif mutation == 'missing_row': bad['rows'].pop()
    else: bad['rows'].append(copy.deepcopy(bad['rows'][0]))
    assert not witness_accepts(bad)
    checks.append('witness_'+mutation+'_rejected')
guard = next(node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=='guard')
pattern = re.search("-match '([^']+)'",ast.literal_eval(guard.body[0].value)).group(1)
for name in ['contract','windows','callback-production','callback-prototype','backend-group','cl']:
    assert re.fullmatch(pattern,name)
    checks.append('guard_'+name+'_matched')
for name in ['powershell','python','explorer']:
    assert not re.fullmatch(pattern,name)
    checks.append('guard_'+name+'_not_falsely_matched')
assert len(checks)==103
previous=json.loads((root/'review/parser-check.json').read_bytes())
assert checks==previous['checks'] and hashlib.sha256(source).hexdigest()==previous['runner_sha256']
print(json.dumps(dict(status='pass',checks=103,runner_sha256=hashlib.sha256(source).hexdigest(),scope='Reproducible pure-data/selected-AST checks only; no orchestration import or execution.')))

#pragma once
#include <cstdint>
#include <cstddef>
#include <memory>
#include <functional>
#include <initializer_list>

// Compute backend abstraction. The inference graph runs its primitive ops
// (matmul, attention, RMSNorm, RoPE) through a Backend so the same model code
// can target CPU now and ROCm / Vulkan later.
//
// This interface is device-agnostic in shape, but host-pointer based: every
// call takes raw host pointers and returns synchronously, so a backend cannot
// own device memory, keep activations resident, or run async. Adding that is
// the prerequisite for any GPU backend -- see docs/ROADMAP.md #4a.
//
// Multi-device / multi-node: the split strategies (per-layer, per-tensor,
// per-row) live at the model layer and are documented in docs/ROADMAP.md; they
// are NOT implemented yet.

namespace backend {

struct Projection {
    uint32_t type;
    const uint8_t* data;
    float* out;
    size_t rows;
};

class Backend {
public:
    virtual ~Backend() = default;

    // Set the worker thread count hint (0 = auto / leave as-is).
    virtual void set_threads(int n) = 0;

    // Number of worker threads this backend will actually use (after the last
    // set_threads, or auto-detected). Used to size parallelism that happens in
    // the model layer (e.g. attention heads).
    virtual int threads_available() const = 0;

    // Invoke once on the caller and complete all cleanup before returning.
    virtual void run_prefill(const std::function<void()>& work) { work(); }

    // Dot product of one Q8_0 block row (nblocks*32 values) against `x`.
    virtual float dot_q8_0(const uint8_t* row, const float* x, size_t nblocks) = 0;

    // out[o] = dot(row_o, x) for all rows o in [0, nout). Row o starts at
    // data + o * nblocks * Q8_0_TYPESIZE.
    virtual void matvec_q8_0(const uint8_t* data, const float* x, float* out,
                             size_t nblocks, size_t nout) = 0;

    // Y[b*nout + o] = dot(row_o, X + b*nin), for all b in [0,nbatch) and o in
    // [0,nout). X and Y are row-major with nbatch rows.
    // Type-generic: the quant type is looked up in quant::Registry, so every
    // block format gets the batched path, not just Q8_0. Rows are iterated
    // outer and the batch inner so each weight row is read once per block.
    virtual void matmul(uint32_t ggml_type, const uint8_t* data, const float* X,
                        float* Y, size_t nin, size_t nout, size_t nbatch) = 0;

    // Independent projections of the same X; outputs must not overlap each
    // other, X, or any weights. All outputs are complete on return.
    virtual void matmul_group(std::initializer_list<Projection> projections,
                              const float* X, size_t nin, size_t nbatch) {
        for (const auto& p : projections)
            matmul(p.type, p.data, X, p.out, nin, p.rows, nbatch);
    }

    // Causal GQA: Q/out are [nbatch, n_head, head_dim]. K/V histories
    // are contiguous per head, separated by kv_head_stride floats.
    // Query b attends through n_past+b.
    virtual void attention(const float* Q, const float* K, const float* V, float* out,
                           int n_head, int n_head_kv, int head_dim,
                           int n_past, int nbatch, size_t kv_head_stride) = 0;

    // Run fn(i) for i in [0, n) across the backend's workers. On failure,
    // finish active participants before propagating an exception. Outputs may
    // be partial; this does not roll back an operation or make submission concurrent.
    virtual void parallel_for(int n, const std::function<void(int)>& fn) = 0;

    // dst[i] = src[i] * rsqrt(mean(src^2) + eps) * w[i]  (RMS norm).
    virtual void rms_norm(float* dst, const float* src, const float* w,
                          size_t n, float eps) = 0;

    // Rotary position embedding on head_dim floats. `cos`/`sin` point at the
    // per-position table (half entries each); the halves of x are interleaved.
    virtual void rope(float* x, const float* cos, const float* sin, int half) = 0;
};

using BackendPtr = std::shared_ptr<Backend>;

} // namespace backend

#pragma once
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <vector>
#if defined(_WIN32)
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#endif

namespace backend {
namespace detail {

class PrefillPlacement {
    std::array<uintptr_t, 6> targets_{};
#if defined(_WIN32)
    struct Participant {
        DWORD_PTR old = 0;
        DWORD thread = 0;
        bool changed = false;
        bool verified = false;
    };
    std::array<Participant, 6> participants_{};
#endif
public:
    explicit PrefillPlacement(bool enabled) {
#if defined(_WIN32)
        if (!enabled || GetActiveProcessorGroupCount() != 1) return;
        DWORD_PTR allowed = 0, system = 0;
        if (!GetProcessAffinityMask(GetCurrentProcess(), &allowed, &system) ||
            !allowed || (allowed & ~system)) return;
        DWORD bytes = 0;
        if (GetLogicalProcessorInformationEx(RelationProcessorCore, nullptr, &bytes) ||
            GetLastError() != ERROR_INSUFFICIENT_BUFFER || !bytes) return;
        std::vector<unsigned char> storage(bytes);
        if (!GetLogicalProcessorInformationEx(RelationProcessorCore,
            reinterpret_cast<PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(storage.data()), &bytes) ||
            bytes > storage.size()) return;
        std::vector<uintptr_t> eligible;
        DWORD_PTR seen = 0;
        int efficiency = -1;
        for (size_t offset = 0; offset < bytes;) {
            if (bytes - offset < 8) return;
            const auto* info = reinterpret_cast<const SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX*>(storage.data() + offset);
            if (info->Size < offsetof(SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX, Processor.GroupMask) + sizeof(GROUP_AFFINITY) ||
                info->Size > bytes - offset || info->Relationship != RelationProcessorCore) return;
            const auto& core = info->Processor;
            if (core.GroupCount != 1 || core.GroupMask[0].Group != 0) return;
            if (efficiency < 0) efficiency = core.EfficiencyClass;
            if (efficiency != core.EfficiencyClass) return;
            const DWORD_PTR mask = core.GroupMask[0].Mask;
            if (!mask || (mask & seen)) return;
            seen |= mask;
            const uintptr_t usable = mask & allowed;
            if (usable) eligible.push_back(usable & (~usable + 1));
            offset += info->Size;
        }
        if ((allowed & ~seen) || eligible.size() < targets_.size()) return;
        std::sort(eligible.begin(), eligible.end());
        std::copy_n(eligible.begin(), targets_.size(), targets_.begin());
#else
        (void)enabled;
#endif
    }

    PrefillPlacement(const PrefillPlacement&) = delete;
    PrefillPlacement& operator=(const PrefillPlacement&) = delete;

    bool enabled() const { return targets_[0] != 0; }

    void apply(int worker) {
#if defined(_WIN32)
        const uintptr_t target = targets_[size_t(worker)];
        GROUP_AFFINITY before{};
        if (!target || !GetThreadGroupAffinity(GetCurrentThread(), &before) ||
            before.Group != 0 || (target & before.Mask) != target) return;
        auto& participant = participants_[size_t(worker)];
        participant.thread = GetCurrentThreadId();
        participant.old = SetThreadAffinityMask(GetCurrentThread(), DWORD_PTR(target));
        participant.changed = participant.old != 0;
        if (!participant.changed) return;
        GROUP_AFFINITY after{};
        participant.verified = GetThreadGroupAffinity(GetCurrentThread(), &after) &&
            after.Group == 0 && after.Mask == target;
#else
        (void)worker;
#endif
    }

    bool applied() const {
#if defined(_WIN32)
        return std::all_of(participants_.begin(), participants_.end(),
            [](const Participant& p) { return p.changed && p.verified; });
#else
        return false;
#endif
    }

    bool needs_restore() const {
#if defined(_WIN32)
        return std::any_of(participants_.begin(), participants_.end(),
            [](const Participant& p) { return p.changed; });
#else
        return false;
#endif
    }

    void restore(int worker) {
#if defined(_WIN32)
        auto& participant = participants_[size_t(worker)];
        if (!participant.changed) return;
        if (GetCurrentThreadId() != participant.thread)
            throw std::runtime_error("CPU prefill restore participant changed");
        if (!SetThreadAffinityMask(GetCurrentThread(), participant.old))
            throw std::runtime_error("CPU prefill placement restore failed");
        participant.changed = false;
        GROUP_AFFINITY after{};
        if (!GetThreadGroupAffinity(GetCurrentThread(), &after) ||
            after.Group != 0 || after.Mask != participant.old)
            throw std::runtime_error("CPU prefill restored mask verification failed");
#else
        (void)worker;
#endif
    }
};

}
}

