#pragma once
#include <cstdint>
#include <cstring>

// IEEE 754 binary16 <-> binary32 conversion, from scratch (no libs).

inline uint16_t f32_to_f16(float f) {
    union { uint32_t u; float f; } x;
    x.f = f;
    uint32_t s = (x.u >> 16) & 0x8000u;   // sign bit (bit 15 of half)
    uint32_t e = (x.u >> 23) & 0xffu;     // f32 exponent
    uint32_t m = x.u & 0x7fffffu;         // f32 mantissa

    if (e == 0xffu) {                     // inf / nan
        return (uint16_t)(s | 0x7c00u | (m ? 0x0200u : 0u));
    }

    int es = (int)e - 127 + 15;           // rebias to f16
    if (es >= 31) {                        // overflow -> inf
        return (uint16_t)(s | 0x7c00u);
    }
    if (es <= 0) {                         // subnormal f16
        if (es < -10) {                    // underflow to zero
            return (uint16_t)s;
        }
        // Subnormal half: the result is the full 24-bit significand shifted
        // right by (14 - es), with no implicit leading 1 left in it.
        // The 0xfff round-to-nearest bias that the NORMAL path uses belongs
        // before a pending 13-bit shift; applying it here added 4095 to an
        // already-shifted 10-bit value and produced a normal half roughly
        // 200x too large.
        m |= 0x800000u;                    // restore implicit leading 1
        const uint32_t shift = (uint32_t)(14 - es);   // 14..24
        uint32_t half = m >> shift;
        const uint32_t rem = m & ((1u << shift) - 1u);
        const uint32_t halfway = 1u << (shift - 1);
        if (rem > halfway || (rem == halfway && (half & 1u))) half++;
        return (uint16_t)(s | half);
    }
    uint32_t h = (m >> 13) + ((m & 0x1000u) ? 1u : 0u); // round-to-nearest
    return (uint16_t)(s | ((uint32_t)es << 10) | h);
}

inline float f16_to_f32(uint16_t h) {
    uint32_t sign = (uint32_t)(h & 0x8000u) << 16;
    uint32_t e = (h >> 10) & 0x1fu;
    uint32_t m = h & 0x3ffu;
    uint32_t u;
    if (e == 0) {
        if (m == 0) {
            u = sign;                      // zero
        } else {
            // Subnormal half: value is m * 2^-24, with no implicit leading 1.
            // Shift left until bit 10 becomes that implicit 1; after k shifts
            // the value is (1+frac) * 2^(-14-k), so the f32 exponent field is
            // 113 - k. Incrementing instead of decrementing here made every
            // subnormal 2^(2k) too large -- 16x for the k=2 case that Q6_K
            // super-block scales land in.
            uint32_t k = 0;
            while ((m & 0x400u) == 0) { m <<= 1; k++; }
            m &= 0x3ffu;
            u = sign | ((113u - k) << 23) | (m << 13);
        }
    } else if (e == 0x1fu) {               // inf / nan
        u = sign | 0x7f800000u | (m << 13);
    } else {
        u = sign | ((e + 112) << 23) | (m << 13);
    }
    float f;
    std::memcpy(&f, &u, 4);
    return f;
}

#pragma once
#include <string>
#include <vector>
#include <utility>
#include <stdexcept>
#include <cstdint>
#include <cstdlib>
#include <cctype>

// Minimal recursive-descent JSON parser, written from scratch (no libs).

namespace jmini {

struct Value;
using Object = std::vector<std::pair<std::string, Value>>;
using Array  = std::vector<Value>;

struct Value {
    enum class T { Null, Bool, Number, String, Array, Object } t = T::Null;
    bool b = false;
    double num = 0;
    std::string str;
    Array arr;
    Object obj;

    bool isObject() const { return t == T::Object; }
    bool isArray()  const { return t == T::Array; }
    bool isString() const { return t == T::String; }
    bool isNumber() const { return t == T::Number; }

    const Value* get(const std::string& k) const {
        if (t != T::Object) return nullptr;
        for (const auto& p : obj) if (p.first == k) return &p.second;
        return nullptr;
    }
    const std::string& asString() const { return str; }
    double asNumber() const { return num; }
    const Array& asArray() const { return arr; }
};

class Parser {
    const std::string& s;
    size_t i = 0;

    void ws() { while (i < s.size() && (s[i]==' '||s[i]=='\t'||s[i]=='\n'||s[i]=='\r')) i++; }
    char peek() {
        if (i >= s.size()) throw std::runtime_error("json: unexpected end of input");
        return s[i];
    }
    void expect(char c) { ws(); if (peek() != c) throw std::runtime_error("json: expected character"); i++; }

    std::string parseString() {
        expect('"');
        std::string out;
        while (i < s.size()) {
            char c = s[i++];
            if (c == '"') return out;
            if (c == '\\') {
                char e = s[i++];
                switch (e) {
                    case '"':  out += '"';  break;
                    case '\\': out += '\\'; break;
                    case '/':  out += '/';  break;
                    case 'b':  out += '\b'; break;
                    case 'f':  out += '\f'; break;
                    case 'n':  out += '\n'; break;
                    case 'r':  out += '\r'; break;
                    case 't':  out += '\t'; break;
                    case 'u': {
                        if (i + 4 <= s.size()) {
                            unsigned v = (unsigned)std::strtoul(s.substr(i, 4).c_str(), nullptr, 16);
                            out += (char)v;
                            i += 4;
                        }
                        break;
                    }
                    default: out += e;
                }
            } else out += c;
        }
        throw std::runtime_error("json: unterminated string");
    }

    Value parseObject() {
        Value v; v.t = Value::T::Object;
        expect('{'); ws();
        if (peek() == '}') { i++; return v; }
        for (;;) {
            ws();
            std::string key = parseString();
            ws(); expect(':');
            Value val = parseValue();
            v.obj.push_back({ std::move(key), std::move(val) });
            ws();
            char c = peek();
            if (c == ',') { i++; continue; }
            if (c == '}') { i++; break; }
            throw std::runtime_error("json: object syntax error");
        }
        return v;
    }

    Value parseArray() {
        Value v; v.t = Value::T::Array;
        expect('['); ws();
        if (peek() == ']') { i++; return v; }
        for (;;) {
            Value val = parseValue();
            v.arr.push_back(std::move(val));
            ws();
            char c = peek();
            if (c == ',') { i++; continue; }
            if (c == ']') { i++; break; }
            throw std::runtime_error("json: array syntax error");
        }
        return v;
    }

    Value parseValue() {
        ws();
        char c = peek();
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') { Value v; v.t = Value::T::String; v.str = parseString(); return v; }
        if (c == 't') { expect('t'); expect('r'); expect('u'); expect('e'); Value v; v.t = Value::T::Bool; v.b = true; return v; }
        if (c == 'f') { expect('f'); expect('a'); expect('l'); expect('s'); expect('e'); Value v; v.t = Value::T::Bool; v.b = false; return v; }
        if (c == 'n') { expect('n'); expect('u'); expect('l'); expect('l'); return Value(); }
        std::string num;
        if (c == '-') { num += c; i++; }
        while (i < s.size() && (std::isdigit((unsigned char)s[i]) || s[i]=='.'||s[i]=='e'||s[i]=='E'||s[i]=='+'||s[i]=='-')) num += s[i++];
        Value v; v.t = Value::T::Number; v.num = std::strtod(num.c_str(), nullptr); return v;
    }

public:
    explicit Parser(const std::string& str) : s(str) {}

    Value parse() {
        ws();
        Value v = parseValue();
        ws();
        if (i != s.size()) throw std::runtime_error("json: trailing data after document");
        return v;
    }
};

inline Value parse(const std::string& s) { return Parser(s).parse(); }

} // namespace jmini

#pragma once
#include <cstdint>
#include <string>
#include <vector>
#include <memory>
#include <functional>

// Pluggable model-file format abstraction. A format knows how to open a file
// and enumerate its tensors plus metadata. GGUF (format/gguf.hpp) is the first
// implementation; future formats (safetensors, raw) implement the same
// interface so the rest of the stack never cares which container was used.
namespace format {

// A single tensor as described by the file's metadata (not yet loaded).
struct Tensor {
    std::string name;
    std::vector<uint64_t> shape; // shape[0] is the fastest dim (ne[0])
    uint32_t type = 0;           // GGML type id (see format/gguf.hpp)
};

class ModelFormat {
public:
    virtual ~ModelFormat() = default;

    // List tensors in the order their data appears in the file.
    virtual std::vector<Tensor> tensors() const = 0;

    // Read a string metadata key. Returns empty if absent.
    virtual std::string metadata_string(const std::string& key) const = 0;

    // Read an integer metadata key. Returns 0 if absent.
    virtual uint64_t metadata_u64(const std::string& key) const = 0;
};

using ModelFormatPtr = std::shared_ptr<ModelFormat>;

// Completed tensor payload bytes, excluding metadata and padding; called synchronously.
using LoadProgress = std::function<void(size_t completed, size_t total)>;

// Open a model file, auto-detecting the format from its header. Returns nullptr
// if the format is not recognized.
ModelFormatPtr open(const std::string& path, const LoadProgress& progress = {});

} // namespace format

#pragma once
#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <utility>
#include <iostream>
#include <fstream>
#include <stdexcept>
#include <algorithm>

#include "format/format.hpp"

// GGUF file format reader/writer, implemented from scratch.
// Implements GGUF v3 + GGML_TYPE_Q8_0 and GGML_TYPE_F32 tensors.
// Spec reference (llama.cpp gguf.h):
//   header: magic(u32) version(u32) tensor_count(u64) metadata_kv_count(u64)
//   metadata KVs: key(string) type(u32) value
//   padding to ALIGNMENT
//   tensor infos: name(string) n_dims(u32) dims(u64[n]) type(u32) offset(u64)
//                 + padding to ALIGNMENT after each
//   padding to ALIGNMENT
//   tensor data (each padded to ALIGNMENT), offset relative to data start
// string = u64 length + raw bytes (no terminator)

namespace gguf {

constexpr uint32_t MAGIC     = 0x46554747u; // 'GGUF'
constexpr uint32_t VERSION   = 3;
constexpr size_t   ALIGNMENT = 32;

constexpr uint32_t GGML_TYPE_F32  = 0;
constexpr uint32_t GGML_TYPE_Q4_0 = 2;
constexpr uint32_t GGML_TYPE_Q4_1 = 3;
constexpr uint32_t GGML_TYPE_Q8_0 = 8;
constexpr uint32_t GGML_TYPE_Q4_K = 12;
constexpr uint32_t GGML_TYPE_Q5_K = 13;
constexpr uint32_t GGML_TYPE_Q6_K = 14;
constexpr size_t   Q5_K_BLOCK    = 256;  // K-quant super-block
constexpr size_t   Q5_K_TYPESIZE = 176;  // Q4_K plus 32 bytes of fifth bits
constexpr size_t   Q4_K_BLOCK    = 256;  // K-quant super-block
constexpr size_t   Q4_K_TYPESIZE = 144;  // 2 f16 + 12 packed 6-bit + 128 nibbles
constexpr size_t   Q4_1_BLOCK    = 32;   // values per block
constexpr size_t   Q4_1_TYPESIZE = 20;   // f16 scale + f16 min + 32 nibbles
constexpr size_t   Q6_K_BLOCK    = 256;  // K-quant super-block
constexpr size_t   Q6_K_TYPESIZE = 210;  // 128 low + 64 high + 16 scales + f16
constexpr size_t   Q4_0_BLOCK    = 32;   // values per block
constexpr size_t   Q4_0_TYPESIZE = 18;   // 2-byte f16 scale + 32 nibbles
constexpr size_t   Q8_0_BLOCK    = 32;   // values per block
constexpr size_t   Q8_0_TYPESIZE = 34;   // 2-byte f16 scale + 32 int8

// GGUF value types
enum : uint32_t {
    V_UINT8 = 0, V_INT8 = 1, V_UINT16 = 2, V_INT16 = 3, V_UINT32 = 4,
    V_INT32 = 5, V_FLOAT32 = 6, V_BOOL = 7, V_STRING = 8, V_ARRAY = 9,
    V_UINT64 = 10, V_INT64 = 11, V_FLOAT64 = 12
};

struct MetaValue {
    uint32_t vtype = 0;
    uint64_t u = 0;      // unsigned / array element type
    int64_t  i = 0;
    uint32_t fb = 0;     // float32 bits
    double   f64 = 0;
    bool     b = false;
    std::string s;
    std::vector<MetaValue> arr;
};

struct TensorInfo {
    std::string name;
    std::vector<uint64_t> ne; // dims; ne[0] is fastest
    uint32_t type = 0;
    uint64_t offset = 0;

    uint64_t n_elements() const {
        uint64_t n = 1;
        for (auto d : ne) n *= d;
        return n;
    }
    uint64_t data_size() const {
        if (type == GGML_TYPE_Q8_0) return (n_elements() / Q8_0_BLOCK) * Q8_0_TYPESIZE;
        if (type == GGML_TYPE_Q4_0) return (n_elements() / Q4_0_BLOCK) * Q4_0_TYPESIZE;
        if (type == GGML_TYPE_Q4_1) return (n_elements() / Q4_1_BLOCK) * Q4_1_TYPESIZE;
        if (type == GGML_TYPE_Q4_K) return (n_elements() / Q4_K_BLOCK) * Q4_K_TYPESIZE;
        if (type == GGML_TYPE_Q5_K) return (n_elements() / Q5_K_BLOCK) * Q5_K_TYPESIZE;
        if (type == GGML_TYPE_Q6_K) return (n_elements() / Q6_K_BLOCK) * Q6_K_TYPESIZE;
        if (type == GGML_TYPE_F32)  return n_elements() * 4;
        throw std::runtime_error("unsupported tensor type in data_size");
    }
};

struct GGUFModel {
    std::vector<std::pair<std::string, MetaValue>> kv;
    std::vector<TensorInfo> tensors;
    // All tensor data in ONE contiguous allocation. This used to be a separate
    // heap block per tensor (399 of them on Qwen3-8B), which fragments the very
    // weight stream that decode is bandwidth bound on.
    std::vector<uint8_t> blob;
    std::vector<size_t> offsets;

    const uint8_t* tensor_data(size_t i) const { return blob.data() + offsets[i]; }
    uint8_t* tensor_data(size_t i) { return blob.data() + offsets[i]; }
    size_t tensor_bytes(size_t i) const { return (size_t)tensors[i].data_size(); }

    // Append one tensor's bytes. Callers that know the total should reserve
    // blob first; read_gguf sizes it exactly and reads in place instead.
    void add_tensor_data(const std::vector<uint8_t>& bytes) {
        blob.resize((blob.size() + alignof(float) - 1) / alignof(float) * alignof(float));
        offsets.push_back(blob.size());
        blob.insert(blob.end(), bytes.begin(), bytes.end());
    }
};

inline std::string read_string(std::istream& is) {
    uint64_t n;
    is.read((char*)&n, 8);
    std::string s;
    s.resize((size_t)n);
    if (n) is.read(&s[0], (std::streamsize)n);
    return s;
}

inline void write_string(std::ostream& os, const std::string& s) {
    uint64_t n = s.size();
    os.write((const char*)&n, 8);
    os.write(s.data(), (std::streamsize)s.size());
}

inline void pad_to(std::ostream& os, size_t align) {
    size_t pos = (size_t)os.tellp();
    size_t pad = (align - (pos % align)) % align;
    for (size_t k = 0; k < pad; k++) os.put(0);
}

// Reads a bare value (no type tag) given its GGUF value type.
// In GGUF, array elements are stored WITHOUT their own type tag: the array
// header carries a single element type, then each element is written as just
// its value. So we must read/write elements as bare typed values, not as full
// (tagged) metadata values.
inline MetaValue read_typed_value(std::istream& is, uint32_t t) {
    MetaValue v;
    v.vtype = t;
    switch (t) {
        case V_UINT8:  { uint8_t  x; is.read((char*)&x, 1); v.u = x; break; }
        case V_INT8:   { int8_t   x; is.read((char*)&x, 1); v.i = x; break; }
        case V_UINT16: { uint16_t x; is.read((char*)&x, 2); v.u = x; break; }
        case V_INT16:  { int16_t  x; is.read((char*)&x, 2); v.i = x; break; }
        case V_UINT32: { uint32_t x; is.read((char*)&x, 4); v.u = x; break; }
        case V_INT32:  { int32_t  x; is.read((char*)&x, 4); v.i = x; break; }
        case V_FLOAT32:{ float    x; is.read((char*)&x, 4); std::memcpy(&v.fb, &x, 4); break; }
        case V_BOOL:   { uint8_t  x; is.read((char*)&x, 1); v.b = x; break; }
        case V_STRING: v.s = read_string(is); break;
        case V_ARRAY: {
            uint32_t et; uint64_t cnt;
            is.read((char*)&et, 4);
            is.read((char*)&cnt, 8);
            v.u = et;
            v.arr.resize((size_t)cnt);
            for (auto& e : v.arr) e = read_typed_value(is, et);
            break;
        }
        case V_UINT64:  { uint64_t x; is.read((char*)&x, 8); v.u = x; break; }
        case V_INT64:   { int64_t  x; is.read((char*)&x, 8); v.i = x; break; }
        case V_FLOAT64: { double   x; is.read((char*)&x, 8); v.f64 = x; break; }
        default: throw std::runtime_error("unknown GGUF metadata value type");
    }
    return v;
}

inline MetaValue read_meta_value(std::istream& is) {
    uint32_t t;
    is.read((char*)&t, 4);
    return read_typed_value(is, t);
}

inline void write_typed_value(std::ostream& os, const MetaValue& v) {
    switch (v.vtype) {
        case V_UINT8:   { uint8_t  x = (uint8_t)v.u;  os.write((const char*)&x, 1); break; }
        case V_INT8:    { int8_t   x = (int8_t)v.i;   os.write((const char*)&x, 1); break; }
        case V_UINT16:  { uint16_t x = (uint16_t)v.u; os.write((const char*)&x, 2); break; }
        case V_INT16:   { int16_t  x = (int16_t)v.i;  os.write((const char*)&x, 2); break; }
        case V_UINT32:  { uint32_t x = (uint32_t)v.u; os.write((const char*)&x, 4); break; }
        case V_INT32:   { int32_t  x = (int32_t)v.i;  os.write((const char*)&x, 4); break; }
        case V_FLOAT32: { float x; std::memcpy(&x, &v.fb, 4); os.write((const char*)&x, 4); break; }
        case V_BOOL:    { uint8_t  x = v.b ? 1 : 0;   os.write((const char*)&x, 1); break; }
        case V_STRING:  write_string(os, v.s); break;
        case V_ARRAY: {
            uint32_t et = (uint32_t)v.u;
            uint64_t cnt = v.arr.size();
            os.write((const char*)&et, 4);
            os.write((const char*)&cnt, 8);
            for (const auto& e : v.arr) write_typed_value(os, e);
            break;
        }
        case V_UINT64:  { uint64_t x = v.u; os.write((const char*)&x, 8); break; }
        case V_INT64:   { int64_t  x = v.i; os.write((const char*)&x, 8); break; }
        case V_FLOAT64: { double   x = v.f64; os.write((const char*)&x, 8); break; }
        default: throw std::runtime_error("unknown GGUF metadata value type");
    }
}

inline void write_meta_value(std::ostream& os, const MetaValue& v) {
    os.write((const char*)&v.vtype, 4);
    write_typed_value(os, v);
}

inline void write_gguf(const GGUFModel& m, const std::string& path) {
    std::ofstream os(path, std::ios::binary);
    if (!os) throw std::runtime_error("cannot open file for writing: " + path);

    uint32_t magic = MAGIC;
    uint32_t ver   = VERSION;
    uint64_t ntc   = m.tensors.size();
    uint64_t nkv   = m.kv.size();
    os.write((const char*)&magic, 4);
    os.write((const char*)&ver,   4);
    os.write((const char*)&ntc,   8);
    os.write((const char*)&nkv,   8);

    for (const auto& kv : m.kv) {
        write_string(os, kv.first);
        write_meta_value(os, kv.second);
    }

    // Tensor infos are packed contiguously (no padding between them).
    uint64_t data_offset = 0; // aligned start of each tensor's data
    for (const auto& t : m.tensors) {
        write_string(os, t.name);
        uint32_t nd = (uint32_t)t.ne.size();
        os.write((const char*)&nd, 4);
        for (uint64_t d : t.ne) os.write((const char*)&d, 8);
        os.write((const char*)&t.type, 4);
        os.write((const char*)&data_offset, 8);
        uint64_t end = data_offset + t.data_size();
        data_offset = (end + (ALIGNMENT - 1)) & ~(uint64_t)(ALIGNMENT - 1);
    }
    pad_to(os, ALIGNMENT);

    for (size_t i = 0; i < m.tensors.size(); i++) {
        os.write((const char*)m.tensor_data(i), (std::streamsize)m.tensor_bytes(i));
        pad_to(os, ALIGNMENT);
    }
}

inline GGUFModel read_gguf(const std::string& path, const format::LoadProgress& progress = {}) {
    std::ifstream is(path, std::ios::binary);
    if (!is) throw std::runtime_error("cannot open file: " + path);
    is.exceptions(std::ios::failbit | std::ios::badbit);

    GGUFModel m;
    uint32_t magic;
    uint32_t ver;
    uint64_t ntc, nkv;
    is.read((char*)&magic, 4);
    if (magic != MAGIC) throw std::runtime_error("not a GGUF file (bad magic)");
    is.read((char*)&ver, 4);
    is.read((char*)&ntc, 8);
    is.read((char*)&nkv, 8);

    for (uint64_t k = 0; k < nkv; k++) {
        std::string key = read_string(is);
        m.kv.emplace_back(std::move(key), read_meta_value(is));
    }

    // Tensor infos are packed contiguously (no padding between them).
    for (uint64_t i = 0; i < ntc; i++) {
        TensorInfo t;
        t.name = read_string(is);
        uint32_t nd;
        is.read((char*)&nd, 4);
        t.ne.resize(nd);
        for (uint32_t d = 0; d < nd; d++) is.read((char*)&t.ne[d], 8);
        is.read((char*)&t.type, 4);
        is.read((char*)&t.offset, 8);
        m.tensors.push_back(std::move(t));
    }
    // Only the tensor-data section start is aligned to ALIGNMENT.
    { size_t pos = (size_t)is.tellg(); size_t pad = (ALIGNMENT - (pos % ALIGNMENT)) % ALIGNMENT; is.seekg(pos + pad); }
    size_t data_start = (size_t)is.tellg();

    // Size the blob exactly, then read each tensor straight into place: no
    // per-tensor temporary and no reallocation of an 8 GB buffer.
    size_t total = 0;
    size_t payload = 0;
    m.offsets.reserve(m.tensors.size());
    for (const auto& t : m.tensors) {
        // Odd quantized block counts must not misalign a following F32 tensor.
        total = (total + alignof(float) - 1) / alignof(float) * alignof(float);
        m.offsets.push_back(total);
        total += (size_t)t.data_size();
        payload += (size_t)t.data_size();
    }
    if (progress && payload) progress(0, payload);
    m.blob.resize(total);
    size_t completed = 0;
    for (size_t i = 0; i < m.tensors.size(); i++) {
        is.seekg(data_start + m.tensors[i].offset);
        const size_t bytes = m.tensor_bytes(i);
        for (size_t offset = 0; offset < bytes;) {
            const size_t chunk = std::min(bytes - offset, size_t(8 * 1024 * 1024));
            is.read((char*)m.tensor_data(i) + offset, (std::streamsize)chunk);
            offset += chunk;
            completed += chunk;
            if (progress && completed < payload) progress(completed, payload);
        }
    }
    if (progress) progress(completed, payload);
    return m;
}

// GGUF is the reference implementation of the format::ModelFormat interface.
// It wraps a GGUFModel (already read into memory) and exposes its tensors and
// metadata through the format-agnostic view.
class GGUFFormat final : public format::ModelFormat {
public:
    explicit GGUFFormat(gguf::GGUFModel m) : m_(std::move(m)) {}

    std::vector<format::Tensor> tensors() const override {
        std::vector<format::Tensor> out;
        out.reserve(m_.tensors.size());
        for (const auto& t : m_.tensors) out.push_back({ t.name, t.ne, t.type });
        return out;
    }

    std::string metadata_string(const std::string& key) const override {
        for (const auto& kv : m_.kv)
            if (kv.first == key && kv.second.vtype == gguf::V_STRING) return kv.second.s;
        return "";
    }

    uint64_t metadata_u64(const std::string& key) const override {
        for (const auto& kv : m_.kv) {
            if (kv.first != key) continue;
            switch (kv.second.vtype) {
                case gguf::V_UINT8:  return kv.second.u;
                case gguf::V_UINT16: return kv.second.u;
                case gguf::V_UINT32: return kv.second.u;
                case gguf::V_UINT64: return kv.second.u;
                case gguf::V_INT8:   return (uint64_t)kv.second.i;
                case gguf::V_INT16:  return (uint64_t)kv.second.i;
                case gguf::V_INT32:  return (uint64_t)kv.second.i;
                case gguf::V_INT64:  return (uint64_t)kv.second.i;
                default: return 0;
            }
        }
        return 0;
    }

private:
    gguf::GGUFModel m_;
};

} // namespace gguf

// Auto-detect the format from the file header and open it. Currently only GGUF
// is implemented; the magic check is the extension point for future formats.
inline format::ModelFormatPtr format::open(const std::string& path, const LoadProgress& progress) {
    std::ifstream is(path, std::ios::binary);
    if (!is) throw std::runtime_error("cannot open file: " + path);
    uint32_t magic = 0;
    is.read((char*)&magic, 4);
    if (is && magic == gguf::MAGIC) return std::make_shared<gguf::GGUFFormat>(gguf::read_gguf(path, progress));
    return nullptr;
}

#pragma once
#include <cstdint>
#include <cmath>
#include <string>
#include <vector>
#include <algorithm>
#include <functional>

#include "model/arch_qwen.hpp"
#include "tokenizer/tokenizer.hpp"
#include "inference/sampler.hpp"
#include "inference/chat.hpp"

// High-level inference drivers built on the model + tokenizer: prefill,
// generate, and the generate / perplexity / chat entry points.

namespace infer {

// Feed every id in `ids` through the model (prefill / continue), updating the
// KV cache. Returns the logits predicted by the last token (i.e. the
// distribution over the next token).
inline std::vector<float> prefill(infer::Model& model,
                                  const std::vector<uint32_t>& ids) {
    return model.prefill(ids);
}

// Find a vocab token whose string contains `sub`, or -1.
inline int find_token_by_substr(const bpe::Tokenizer& tok, const std::string& sub) {
    for (size_t i = 0; i < tok.vocab.size(); i++)
        if (tok.vocab[i].find(sub) != std::string::npos) return (int)i;
    return -1;
}

// Generate tokens starting from `logits` (the prediction after the last fed
// token), stopping at eos. Returns generated ids (excluding the eos token).
// Text callbacks run synchronously and may split a UTF-8 character between chunks.
// Legacy reasoning filters need the full sequence because later markers can discard earlier text.
inline std::vector<uint32_t> generate(infer::Model& model, bpe::Tokenizer& tok,
                                      const infer::GenParams& gp, infer::RNG& rng,
                                      std::vector<float> logits,
                                      const std::function<void(const std::string&)>& emit = {}) {
    uint32_t eos = (uint32_t)((tok.eos_id >= 0) ? tok.eos_id : 0);
    const int tstart = gp.show_thinking ? -1 : find_token_by_substr(tok, "thinking_start");
    const int tend = gp.show_thinking ? -1 : find_token_by_substr(tok, "thinking_end");
    const int astart = gp.show_thinking ? -1 : find_token_by_substr(tok, "answer_start");
    const int aend = gp.show_thinking ? -1 : find_token_by_substr(tok, "answer_end");
    const bool buffered = tstart >= 0 || astart >= 0 || aend >= 0;
    std::vector<uint32_t> gen;
    std::string decoded;
    for (int t = 0; t < gp.max_tokens; t++) {
        uint32_t id = infer::sample(logits, gp.temp, gp.top_k, gp.top_p, gp.penalty, gen, rng);
        if (id == eos) break;
        gen.push_back(id);
        const std::string text = tok.decode({ id });
        if (emit && !buffered) emit(text);
        decoded += text;
        if (!gp.stop.empty() && decoded.find(gp.stop) != std::string::npos) break;
        logits = model.step((int)id); // predict token after `id`
    }

    size_t begin = 0;
    size_t end = gen.size();
    if (buffered) {
        if (tstart >= 0) {
            auto ts = std::find(gen.begin(), gen.end(), (uint32_t)tstart);
            if (ts != gen.end()) {
                auto te = std::find(gen.begin(), gen.end(), (uint32_t)tend);
                begin = (te != gen.end()) ? (size_t)(te - gen.begin() + 1) : gen.size();
            }
        }
        if (astart >= 0) {
            auto as = std::find(gen.begin(), gen.end(), (uint32_t)astart);
            if (as != gen.end()) begin = (size_t)(as - gen.begin() + 1);
        }
        if (aend >= 0) {
            auto ae = std::find(gen.begin(), gen.end(), (uint32_t)aend);
            if (ae != gen.end()) end = (size_t)(ae - gen.begin());
        }
    }

    if (emit && buffered)
        for (size_t i = begin; i < end; i++) emit(tok.decode({ gen[i] }));
    return gen;
}

} // namespace infer

#pragma once
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

#include "model/arch_qwen.hpp"

namespace infer {

struct PerplexityResult {
    size_t used_tokens = 0;
    size_t scored_tokens = 0;
    size_t chunks = 0;
    double nll = 0.0;

    double mean_nll() const { return nll / (double)scored_tokens; }
};

inline PerplexityResult perplexity(Model& model, const std::vector<uint32_t>& ids,
                                   int context_size = 0, int max_chunks = 0) {
    if (ids.size() < 2) throw std::runtime_error("perplexity: need at least 2 tokens");
    const int context = context_size == 0 ? model.context_length() : context_size;
    if (context < 2 || context > model.context_length())
        throw std::runtime_error("perplexity: context size must be between 2 and model context " +
                                 std::to_string(model.context_length()));
    if (max_chunks < 0) throw std::runtime_error("perplexity: chunks must be nonnegative");

    PerplexityResult result;
    for (size_t begin = 0; begin < ids.size();) {
        const size_t count = std::min((size_t)context, ids.size() - begin);
        if (count < 2 || (max_chunks > 0 && result.chunks >= (size_t)max_chunks)) break;
        model.reset();
        std::vector<float> logits = model.step((int)ids[begin]);
        for (size_t i = begin + 1; i < begin + count; i++) {
            const uint32_t target = ids[i];
            float maxv = -1e30f;
            for (float l : logits) maxv = std::max(maxv, l);
            double sum = 0.0;
            for (float l : logits) sum += std::exp((double)l - maxv);
            const double logsumexp = maxv + std::log(sum);
            result.nll -= (double)logits[target] - logsumexp;
            // The last token is a target only; its next-token logits are unused.
            if (i + 1 < begin + count) logits = model.step((int)target);
        }
        result.used_tokens += count;
        result.scored_tokens += count - 1;
        result.chunks++;
        begin += count;
    }
    return result;
}

} // namespace infer

#pragma once
#include <cstdint>
#include <cmath>
#include <string>
#include <vector>
#include <algorithm>
#include <unordered_set>

// Sampling logic and generation parameters, split out of the CLI so the same
// sampler can drive generate, perplexity, and chat.

namespace infer {

// Minimal xorshift64 PRNG (no <random> dependency; deterministic + portable).
struct RNG {
    uint64_t s = 0x9E3779B97F4A7C15ull;
    void seed(uint64_t x) { if (x) s = x; }
    uint64_t next() {
        uint64_t x = s;
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        s = x;
        return x;
    }
    // uniform float in [0,1)
    float unit() { return (float)((next() >> 40) * (1.0 / 16777216.0)); }
};

struct GenParams {
    int max_tokens = 64;
    float temp = 0.8f;
    int top_k = 40;
    float top_p = 0.95f;
    int threads = 0;        // 0 = auto; used for generation (decode)
    int threads_batch = 0;  // 0 = same as threads; used for prefill
    int ubatch = 0;         // physical batch for prefill (0 = default 512)
    float penalty = 1.0f;   // repetition penalty (>= 1)
    uint64_t seed = 0;      // 0 = non-deterministic
    std::string stop;       // stop generating when decoded output contains this
    bool show_prompt_tokens = false;
    bool show_thinking = false; // show Qwen3 <thinking> block
};

// Temperature + top-k + top-p nucleus sampling with repetition penalty.
// `penalty` >= 1: divide the score of each already-generated token by penalty
// to discourage repeats. Returns the chosen token id.
inline uint32_t sample(const std::vector<float>& logits, float temp, int top_k,
                       float top_p, float penalty, const std::vector<uint32_t>& gen,
                       RNG& rng) {
    size_t n = logits.size();

    std::vector<std::pair<float, uint32_t>> ranked;
    ranked.reserve(n);
    for (size_t i = 0; i < n; i++) ranked.push_back({ logits[i], (uint32_t)i });

    // repetition penalty
    if (penalty > 0.0f && penalty != 1.0f && !gen.empty()) {
        std::unordered_set<uint32_t> seen;
        for (uint32_t id : gen) seen.insert(id);
        for (auto& pr : ranked) {
            if (seen.count(pr.second)) {
                pr.first = (pr.first > 0.0f) ? (pr.first / penalty) : (pr.first * penalty);
            }
        }
    }

    std::sort(ranked.begin(), ranked.end(),
              [](const auto& a, const auto& b) { return a.first > b.first; });

    // top-k truncation
    size_t keep = (top_k > 0 && (size_t)top_k < n) ? (size_t)top_k : n;

    if (temp <= 0.0f) return ranked[0].second; // argmax (no randomness)

    // softmax over the kept window. Temperature is applied exactly once, here:
    // pre-scaling the scores by temp as well would cancel this division and
    // make --temp a no-op at every value > 0.
    float maxv = ranked[0].first;
    std::vector<float> p(keep);
    double sum = 0.0;
    for (size_t i = 0; i < keep; i++) {
        float v = std::exp((ranked[i].first - maxv) / temp);
        p[i] = v;
        sum += v;
    }
    for (size_t i = 0; i < keep; i++) p[i] = (float)(p[i] / sum);

    // top-p nucleus truncation
    size_t nuc = keep;
    if (top_p < 1.0f) {
        float acc = 0.0f;
        nuc = 0;
        while (nuc < keep && acc < top_p) { acc += p[nuc]; nuc++; }
        if (nuc < 1) nuc = 1;
        // renormalize over the nucleus
        float nsum = 0.0f;
        for (size_t i = 0; i < nuc; i++) nsum += p[i];
        for (size_t i = 0; i < nuc; i++) p[i] /= nsum;
    }

    float r = rng.unit();
    float acc = 0.0f;
    for (size_t i = 0; i < nuc; i++) {
        acc += p[i];
        if (r < acc) return ranked[i].second;
    }
    return ranked[nuc - 1].second;
}

} // namespace infer

#pragma once
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <vector>
#include <string>
#include <unordered_map>
#include <cmath>
#include <thread>
#include <stdexcept>

#include "format/gguf.hpp"
#include "core/fp16.hpp"
#include "quant/quant.hpp"
#include "backends/backend.hpp"
#include "model/host_kv_cache.hpp"
#include "backends/cpu/cpu_backend.hpp"

// Qwen3-style transformer forward pass, from scratch. The compute primitives
// (matmul, attention, RMSNorm, RoPE) are delegated to a backend::Backend, so the
// same model code runs on CPU now and other backends later.
// Dense matrices use supported block quants or F32; normalization weights are F32.
// Tensor ne[0] is the input dimension, with each output row contiguous.
// Attention projection width is n_head*head_dim and need not equal n_embd.
// An absent output.weight ties the output projection to token_embd.weight.

namespace infer {

struct QwenConfig {
    int n_layer = 0;
    int n_embd = 0;
    int n_ff = 0;
    int n_head = 0;
    int n_head_kv = 0;
    int head_dim = 0;
    int context_length = 4096;
    float rope_theta = 10000.0f;
    float rms_eps = 1e-6f;
};

inline QwenConfig load_config(const gguf::GGUFModel& m) {
    QwenConfig c;
    auto getu = [&](const std::string& k) -> uint64_t {
        for (const auto& kv : m.kv) {
            if (kv.first == k) {
                if (kv.second.vtype == gguf::V_UINT32) return kv.second.u;
                if (kv.second.vtype == gguf::V_INT32)  return (uint64_t)kv.second.i;
                if (kv.second.vtype == gguf::V_UINT64) return kv.second.u;
                if (kv.second.vtype == gguf::V_INT64)  return (uint64_t)kv.second.i;
            }
        }
        return 0;
    };
    auto getf = [&](const std::string& k) -> float {
        for (const auto& kv : m.kv) {
            if (kv.first == k) {
                if (kv.second.vtype == gguf::V_FLOAT32) { float x; std::memcpy(&x, &kv.second.fb, 4); return x; }
                if (kv.second.vtype == gguf::V_FLOAT64) return (float)kv.second.f64;
            }
        }
        return 0.0f;
    };
    c.n_layer = (int)getu("qwen3.block_count");
    c.n_embd  = (int)getu("qwen3.embedding_length");
    c.n_ff    = (int)getu("qwen3.feed_forward_length");
    c.n_head  = (int)getu("qwen3.attention.head_count");
    c.n_head_kv = (int)getu("qwen3.attention.head_count_kv");
    int kl = (int)getu("qwen3.attention.key_length");
    if (kl <= 0) kl = c.n_embd / c.n_head;
    c.head_dim = kl;
    c.context_length = (int)getu("qwen3.context_length");
    if (c.context_length <= 0) c.context_length = 4096;
    c.rope_theta = getf("qwen3.rope.freq_base");
    if (c.rope_theta <= 0.0f) c.rope_theta = 10000.0f;
    c.rms_eps = getf("qwen3.attention.layer_norm_rms_epsilon");
    if (c.rms_eps <= 0.0f) c.rms_eps = 1e-6f;
    return c;
}

class Model {
public:
    // Construct the model over a GGUF model, using the given backend (defaults
    // to the CPU backend). The model owns a reference to the model data, which
    // must outlive the Model.
    explicit Model(const gguf::GGUFModel& m,
                   backend::BackendPtr backend = backend::make_cpu_backend())
        : m_(&m), b_(std::move(backend)) {
        quant::register_builtins(); // populate the quant registry (idempotent)
        cfg = load_config(m);
        if (cfg.n_layer <= 0 || cfg.n_embd <= 0) throw std::runtime_error("inference: incomplete Qwen3 config in metadata");
        if (cfg.n_head_kv <= 0) cfg.n_head_kv = cfg.n_head;
        // The attention projection width is n_head*head_dim, which only equals
        // n_embd by coincidence on some models (Qwen3-8B: 32*128 == 4096).
        // Qwen3-0.6B/1.7B/4B have head_dim 128 with a smaller n_embd.
        q_dim_ = cfg.n_head * cfg.head_dim;

        for (size_t i = 0; i < m.tensors.size(); i++) tindex_[m.tensors[i].name] = i;

        // Tied embeddings: models without a separate output.weight reuse
        // token_embd.weight as the output projection (same [n_embd, n_vocab]
        // layout), so the head is just a matvec against the embedding matrix.
        out_name_ = tindex_.count("output.weight") ? "output.weight" : "token_embd.weight";
        if (!tindex_.count(out_name_))
            throw std::runtime_error("inference: missing output projection tensor");

        // buffers
        x_.assign(cfg.n_embd, 0.0f);
        h_.assign(cfg.n_embd, 0.0f);
        q_.assign(q_dim_, 0.0f);
        kv_.assign((size_t)cfg.n_head_kv * cfg.head_dim, 0.0f);
        v_.assign((size_t)cfg.n_head_kv * cfg.head_dim, 0.0f);
        attn_.assign(q_dim_, 0.0f);
        gate_.assign(cfg.n_ff, 0.0f);
        up_.assign(cfg.n_ff, 0.0f);
        ffn_.assign(cfg.n_ff, 0.0f);

        cache_ = HostKVCache(cfg.n_layer, cfg.n_head_kv, cfg.head_dim, cfg.context_length);

        // Precompute the RoPE cos/sin table for every position up to the
        // context length. Indexed as [pos*(head_dim/2) + i].
        int half = cfg.head_dim / 2;
        rope_cos_.assign((size_t)cfg.context_length * half, 0.0f);
        rope_sin_.assign((size_t)cfg.context_length * half, 0.0f);
        for (int pos = 0; pos < cfg.context_length; pos++) {
            for (int i = 0; i < half; i++) {
                float fre = std::pow(cfg.rope_theta, -2.0f * (float)i / (float)cfg.head_dim);
                rope_cos_[(size_t)pos * half + i] = std::cos((float)pos * fre);
                rope_sin_[(size_t)pos * half + i] = std::sin((float)pos * fre);
            }
        }
    }

    void set_threads(int n) { b_->set_threads(n); }
    int threads_available() const { return b_->threads_available(); }
    // 0 keeps the default. Changing it invalidates the scratch buffers.
    void set_ubatch(int n) { if (n > 0 && n != ubatch_) { ubatch_ = n; xb_.clear(); } }

    int n_tokens() const { return n_tokens_; }
    int head_dim() const { return cfg.head_dim; }
    int context_length() const { return cfg.context_length; }

    // Run one token through the model (prefill or continue). Returns logits
    // over the full vocabulary.
    std::vector<float> step(int token_id) {
        int pos = n_tokens_;
        // The RoPE table is precomputed for [0, context_length); stepping past
        // it would read off the end of rope_cos_/rope_sin_.
        if (pos >= cfg.context_length)
            throw std::runtime_error("inference: context length exceeded (" +
                                     std::to_string(cfg.context_length) + " tokens)");

        cache_.reserve((size_t)pos + 1, (size_t)n_tokens_);

        // embedding
        dequant_row(tensor("token_embd.weight"), token_id, x_.data());

        for (int l = 0; l < cfg.n_layer; l++) {
            const std::string pre = "blk." + std::to_string(l) + ".";

            // attn norm
            b_->rms_norm(h_.data(), x_.data(),
                         (const float*)tensor_data(pre + "attn_norm.weight"),
                         cfg.n_embd, cfg.rms_eps);

            // q,k,v projections
            b_->matmul_group({projection(pre + "attn_q.weight", q_.data(), size_t(q_dim_)),
                              projection(pre + "attn_k.weight", kv_.data(), size_t(cfg.n_head_kv * cfg.head_dim)),
                              projection(pre + "attn_v.weight", v_.data(), size_t(cfg.n_head_kv * cfg.head_dim))},
                             h_.data(), cfg.n_embd, 1);

            // per-head q/k norms
            const float* qnorm = (const float*)tensor_data(pre + "attn_q_norm.weight");
            const float* knorm = (const float*)tensor_data(pre + "attn_k_norm.weight");
            for (int h = 0; h < cfg.n_head; h++)
                b_->rms_norm(q_.data() + h * cfg.head_dim, q_.data() + h * cfg.head_dim, qnorm, cfg.head_dim, cfg.rms_eps);
            for (int h = 0; h < cfg.n_head_kv; h++)
                b_->rms_norm(kv_.data() + h * cfg.head_dim, kv_.data() + h * cfg.head_dim, knorm, cfg.head_dim, cfg.rms_eps);

            // rope
            {
                int half = cfg.head_dim / 2;
                for (int h = 0; h < cfg.n_head; h++)
                    b_->rope(q_.data() + h * cfg.head_dim,
                             rope_cos_.data() + (size_t)pos * half,
                             rope_sin_.data() + (size_t)pos * half, half);
                for (int h = 0; h < cfg.n_head_kv; h++)
                    b_->rope(kv_.data() + h * cfg.head_dim,
                             rope_cos_.data() + (size_t)pos * half,
                             rope_sin_.data() + (size_t)pos * half, half);
            }

            // store k,v in cache
            cache_.write(l, kv_.data(), v_.data(), (size_t)pos, 1);

            // attention: each q-head writes only its own attn_ slice, so heads
            // can be processed in parallel.
            const float* kcache = cache_.keys(l);
            const float* vcache = cache_.values(l);
            b_->attention(q_.data(), kcache, vcache, attn_.data(),
                          cfg.n_head, cfg.n_head_kv, cfg.head_dim, pos, 1, cache_.head_stride());

            // attn_output projection + residual
            std::fill(h_.begin(), h_.end(), 0.0f);
            matvec(tensor(pre + "attn_output.weight"), attn_.data(), h_.data(), (size_t)q_dim_, cfg.n_embd);
            for (int i = 0; i < cfg.n_embd; i++) x_[i] += h_[i];

            // ffn norm
            b_->rms_norm(h_.data(), x_.data(),
                         (const float*)tensor_data(pre + "ffn_norm.weight"),
                         cfg.n_embd, cfg.rms_eps);

            // gate/up (SwiGLU). Buffers are members: allocating these per layer
            // per token cost 108 heap allocations of n_ff floats on a 36-layer
            // model, every token.
            b_->matmul_group({projection(pre + "ffn_gate.weight", gate_.data(), cfg.n_ff),
                              projection(pre + "ffn_up.weight", up_.data(), cfg.n_ff)},
                             h_.data(), cfg.n_embd, 1);
            for (int i = 0; i < cfg.n_ff; i++) {
                float g = gate_[i] / (1.0f + std::exp(-gate_[i])); // SiLU
                ffn_[i] = g * up_[i];
            }
            // down projection + residual
            std::fill(h_.begin(), h_.end(), 0.0f);
            matvec(tensor(pre + "ffn_down.weight"), ffn_.data(), h_.data(), cfg.n_ff, cfg.n_embd);
            for (int i = 0; i < cfg.n_embd; i++) x_[i] += h_[i];
        }

        // final norm + output projection
        b_->rms_norm(h_.data(), x_.data(),
                     (const float*)tensor_data("output_norm.weight"),
                     cfg.n_embd, cfg.rms_eps);
        const gguf::TensorInfo& out_t = tensor(out_name_);
        size_t n_vocab = out_t.ne[1];
        std::vector<float> logits(n_vocab);
        matvec(out_t, h_.data(), logits.data(), cfg.n_embd, n_vocab);

        n_tokens_++;
        return logits;
    }

    // Process a whole prompt with matrix-matrix matmuls instead of one token at
    // a time. Each weight row is then reused across the batch, which is the
    // difference between prefill being compute bound and paying the entire
    // weight stream once per token.
    // Only the final token's logits are ever needed, so the vocab projection
    // stays a single matvec rather than B of them.
    std::vector<float> prefill(const std::vector<uint32_t>& ids) {
        if (ids.empty()) throw std::runtime_error("inference: empty prompt");
        std::vector<float> logits;
        auto work = [&] {
            ensure_batch_buffers(ids.size());
            size_t i = 0;
            while (i < ids.size()) {
                const int B = (int)std::min((size_t)ubatch(), ids.size() - i);
                const bool last = (i + (size_t)B == ids.size());
                forward_batch(&ids[i], B, last ? &logits : nullptr);
                i += (size_t)B;
            }
        };
        b_->run_prefill(std::ref(work));
        return logits;
    }

    // Clear the KV cache (start a new conversation).
    void reset() {
        n_tokens_ = 0;

    }

private:
    const gguf::GGUFModel* m_;
    backend::BackendPtr b_;
    QwenConfig cfg;
    int q_dim_ = 0;
    int ubatch_ = 512;   // default matches llama.cpp
    std::string out_name_;
    std::unordered_map<std::string, size_t> tindex_;

    std::vector<float> x_, h_, q_, kv_, v_, attn_;
    std::vector<float> gate_, up_, ffn_;
    std::vector<float> xb_, hb_, qb_, kb_, vb_, attnb_, gateb_, upb_, ffnb_;
    HostKVCache cache_;
    std::vector<float> rope_cos_, rope_sin_;
    int n_tokens_ = 0;
    const gguf::TensorInfo& tensor(const std::string& name) const {
        auto it = tindex_.find(name);
        if (it == tindex_.end()) throw std::runtime_error("inference: missing tensor " + name);
        return m_->tensors[it->second];
    }
    const uint8_t* tensor_data(const std::string& name) const {
        return m_->tensor_data(tindex_.at(name));
    }

    // Physical batch: how many tokens go through ONE forward pass of the
    // graph. This is llama.cpp's n_ubatch (-ub), not n_batch: it sets the GEMM
    // width and the scratch buffer sizes. llmx has no logical batch, since
    // there is one sequence and no queue; that distinction only starts to
    // matter with the multi-user server in ROADMAP #7.
    int ubatch() const { return ubatch_; }


    // Sized to the largest chunk this prompt will actually use, so a short
    // prompt does not allocate scratch for a full ubatch (at n_ff 12288 a
    // 512-wide gate/up/ffn is about 25 MB each).
    void ensure_batch_buffers(size_t want) {
        const size_t B = std::min((size_t)ubatch(), std::max<size_t>(want, 1));
        if (xb_.size() >= B * (size_t)cfg.n_embd) return;
        const size_t KV = (size_t)cfg.n_head_kv * cfg.head_dim;
        xb_.assign(B * cfg.n_embd, 0.0f);
        hb_.assign(B * cfg.n_embd, 0.0f);
        qb_.assign(B * (size_t)q_dim_, 0.0f);
        kb_.assign(B * KV, 0.0f);
        vb_.assign(B * KV, 0.0f);
        attnb_.assign(B * (size_t)q_dim_, 0.0f);
        gateb_.assign(B * cfg.n_ff, 0.0f);
        upb_.assign(B * cfg.n_ff, 0.0f);
        ffnb_.assign(B * cfg.n_ff, 0.0f);
    }

    void forward_batch(const uint32_t* ids, int B, std::vector<float>* out_logits) {
        const int pos0 = n_tokens_;
        if (pos0 + B > cfg.context_length)
            throw std::runtime_error("inference: context length exceeded (" +
                                     std::to_string(cfg.context_length) + " tokens)");
        cache_.reserve((size_t)pos0 + (size_t)B, (size_t)n_tokens_);
        const int E = cfg.n_embd, HD = cfg.head_dim, half = HD / 2;
        const size_t KV = (size_t)cfg.n_head_kv * HD;
        const int nt = b_->threads_available();
        // Avoid dispatching short elementwise stages when there are fewer
        // than two rows per worker; small-batch timing regressed without this.
        const auto for_rows = [&](const auto& fn) {
            if (nt <= 1 || B / nt < 2) {
                for (int b = 0; b < B; ++b) fn(b);
            } else {
                b_->parallel_for(B, fn);
            }
        };

        for (int b = 0; b < B; b++)
            dequant_row(tensor("token_embd.weight"), ids[b], xb_.data() + (size_t)b * E);

        for (int l = 0; l < cfg.n_layer; l++) {
            const std::string pre = "blk." + std::to_string(l) + ".";

            const float* anorm = (const float*)tensor_data(pre + "attn_norm.weight");
            for_rows([&](int b) {
                b_->rms_norm(hb_.data() + (size_t)b * E, xb_.data() + (size_t)b * E, anorm, E, cfg.rms_eps);
            });

            b_->matmul_group({projection(pre + "attn_q.weight", qb_.data(), size_t(q_dim_)),
                              projection(pre + "attn_k.weight", kb_.data(), KV),
                              projection(pre + "attn_v.weight", vb_.data(), KV)}, hb_.data(), E, B);

            const float* qn = (const float*)tensor_data(pre + "attn_q_norm.weight");
            const float* kn = (const float*)tensor_data(pre + "attn_k_norm.weight");
            for_rows([&](int b) {
                float* q = qb_.data() + (size_t)b * q_dim_;
                float* k = kb_.data() + (size_t)b * KV;
                for (int h = 0; h < cfg.n_head; h++)
                    b_->rms_norm(q + h * HD, q + h * HD, qn, HD, cfg.rms_eps);
                for (int h = 0; h < cfg.n_head_kv; h++)
                    b_->rms_norm(k + h * HD, k + h * HD, kn, HD, cfg.rms_eps);
                const float* cs = rope_cos_.data() + (size_t)(pos0 + b) * half;
                const float* sn = rope_sin_.data() + (size_t)(pos0 + b) * half;
                for (int h = 0; h < cfg.n_head; h++)    b_->rope(q + h * HD, cs, sn, half);
                for (int h = 0; h < cfg.n_head_kv; h++) b_->rope(k + h * HD, cs, sn, half);
            });

            cache_.write(l, kb_.data(), vb_.data(), (size_t)pos0, (size_t)B);

            const float* kc = cache_.keys(l);
            const float* vc = cache_.values(l);
            b_->attention(qb_.data(), kc, vc, attnb_.data(),
                          cfg.n_head, cfg.n_head_kv, cfg.head_dim, pos0, B, cache_.head_stride());

            matmul(tensor(pre + "attn_output.weight"), attnb_.data(), hb_.data(), (size_t)q_dim_, E, B);
            for (size_t j = 0; j < (size_t)B * E; j++) xb_[j] += hb_[j];

            const float* fnorm = (const float*)tensor_data(pre + "ffn_norm.weight");
            for_rows([&](int b) {
                b_->rms_norm(hb_.data() + (size_t)b * E, xb_.data() + (size_t)b * E, fnorm, E, cfg.rms_eps);
            });

            b_->matmul_group({projection(pre + "ffn_gate.weight", gateb_.data(), cfg.n_ff),
                              projection(pre + "ffn_up.weight", upb_.data(), cfg.n_ff)}, hb_.data(), E, B);
            for_rows([&](int b) {
                const size_t end = (size_t)(b + 1) * cfg.n_ff;
                for (size_t j = (size_t)b * cfg.n_ff; j < end; j++) {
                    const float g = gateb_[j] / (1.0f + std::exp(-gateb_[j]));
                    ffnb_[j] = g * upb_[j];
                }
            });
            matmul(tensor(pre + "ffn_down.weight"), ffnb_.data(), hb_.data(), cfg.n_ff, E, B);
            for (size_t j = 0; j < (size_t)B * E; j++) xb_[j] += hb_[j];
        }

        n_tokens_ += B;

        if (out_logits) {
            b_->rms_norm(h_.data(), xb_.data() + (size_t)(B - 1) * E,
                         (const float*)tensor_data("output_norm.weight"), E, cfg.rms_eps);
            const gguf::TensorInfo& ot = tensor(out_name_);
            const size_t n_vocab = (size_t)ot.ne[1];
            out_logits->assign(n_vocab, 0.0f);
            matvec(ot, h_.data(), out_logits->data(), (size_t)E, n_vocab);
        }
    }

    backend::Projection projection(const std::string& name, float* out, size_t rows) const {
        const auto& t = tensor(name);
        return {t.type, m_->tensor_data(tindex_.at(t.name)), out, rows};
    }

    // Batched matmul. The backend dispatches on the quant type, so every
    // block format takes the same path; there is no per-type branch here.
    void matmul(const gguf::TensorInfo& t, const float* X, float* Y,
                size_t nin, size_t nout, int nbatch) {
        b_->matmul(t.type, m_->tensor_data(tindex_.at(t.name)), X, Y,
                   nin, nout, (size_t)nbatch);
    }

    // Dequantize row `r` of a quantized matrix (nin fastest) into `out`,
    // dispatching on the tensor's type via the quant registry.
    void dequant_row(const gguf::TensorInfo& t, size_t r, float* out) const {
        size_t nin = (size_t)t.ne[0];
        if (t.type == gguf::GGML_TYPE_F32) {
            std::memcpy(out, m_->tensor_data(tindex_.at(t.name)) + r * nin * sizeof(float), nin * sizeof(float));
            return;
        }
        const quant::QuantType* qt = quant::Registry::instance().get(t.type);
        if (!qt || !qt->dequantize) throw std::runtime_error("unsupported tensor type in dequant_row");
        const uint8_t* base = m_->tensor_data(tindex_.at(t.name)) +
            r * (nin / qt->block_size) * qt->type_size;
        qt->dequantize(base, out, nin / qt->block_size);
    }

    // out = W^T x for a single column. Same backend entry point as the
    // batched form, so there is one dispatch path and one place that knows
    // about quant types.
    void matvec(const gguf::TensorInfo& t, const float* x, float* out,
                size_t nin, size_t nout) {
        b_->matmul(t.type, m_->tensor_data(tindex_.at(t.name)), x, out, nin, nout, 1);
    }

};

} // namespace infer

#pragma once
#include <algorithm>
#include <cstddef>
#include <stdexcept>
#include <vector>

namespace infer {

// Physical CPU storage only. The sequence owns its valid length and reset;
// capacity retained across resets is never itself an attention history.
class HostKVCache {
public:
    HostKVCache() = default;
    HostKVCache(size_t layers, size_t heads, size_t width, size_t limit)
        : heads_(heads), width_(width), limit_(limit), k_(layers), v_(layers) {}

    void reserve(size_t want, size_t used) {
        if (used > capacity_ || want < used || want > limit_)
            throw std::runtime_error("KV cache: invalid sequence extent");
        if (want <= capacity_) return;
        const size_t capacity = std::max(want,
            capacity_ > limit_ / 2 ? limit_ : capacity_ * 2);
        std::vector<std::vector<float>> next_k(k_.size()), next_v(v_.size());
        for (size_t l = 0; l < k_.size(); ++l) {
            next_k[l].resize(heads_ * capacity * width_);
            next_v[l].resize(heads_ * capacity * width_);
            if (used) for (size_t h = 0; h < heads_; ++h) {
                std::copy_n(k_[l].data() + h * capacity_ * width_, used * width_,
                            next_k[l].data() + h * capacity * width_);
                std::copy_n(v_[l].data() + h * capacity_ * width_, used * width_,
                            next_v[l].data() + h * capacity * width_);
            }
        }
        k_.swap(next_k);
        v_.swap(next_v);
        capacity_ = capacity;
    }

    void write(size_t layer, const float* k, const float* v, size_t pos, size_t batch) {
        if (layer >= k_.size() || pos > capacity_ || batch > capacity_ - pos)
            throw std::runtime_error("KV cache: write outside storage");
        for (size_t h = 0; h < heads_; ++h) {
            float* kd = k_[layer].data() + (h * capacity_ + pos) * width_;
            float* vd = v_[layer].data() + (h * capacity_ + pos) * width_;
            for (size_t b = 0; b < batch; ++b) {
                std::copy_n(k + (b * heads_ + h) * width_, width_, kd + b * width_);
                std::copy_n(v + (b * heads_ + h) * width_, width_, vd + b * width_);
            }
        }
    }

    const float* keys(size_t layer) const { return k_.at(layer).data(); }
    const float* values(size_t layer) const { return v_.at(layer).data(); }
    size_t head_stride() const { return capacity_ * width_; }

private:
    size_t heads_ = 0, width_ = 0, limit_ = 0, capacity_ = 0;
    std::vector<std::vector<float>> k_, v_;
};

} // namespace infer

#pragma once
#include <cstdint>
#include <cstddef>

#include "core/fp16.hpp"
#include "format/gguf.hpp"

// K-quant block formats. These differ from the simple block types in quant.hpp
// in two ways: the block is a 256-value SUPER-block, and each super-block
// carries per-32-value sub-scales that are themselves quantized to 6 bits
// against a pair of f16 super-block scales.
//
// All of these are READ-ONLY here. llmx must load them because they are what
// the Hugging Face Hub actually hosts, but nothing in llmx produces one and a
// quantizer would be unused code.

namespace quant {

// Unpack the 6-bit sub-scale and sub-min for sub-block j (0..7) out of the
// 12 packed bytes. The first four pairs sit in the low 6 bits of bytes 0..7;
// the last four are split, taking their low 4 bits from bytes 8..11 and their
// high 2 bits from the top of the earlier bytes. Shared by Q4_K and Q5_K.
inline void get_scale_min_k4(int j, const uint8_t* q, uint8_t* d, uint8_t* m) {
    if (j < 4) {
        *d = q[j] & 63;
        *m = q[j + 4] & 63;
    } else {
        *d = (uint8_t)((q[j + 4] & 0xF) | ((q[j - 4] >> 6) << 4));
        *m = (uint8_t)((q[j + 4] >> 4)  | ((q[j - 0] >> 6) << 4));
    }
}

// Q4_K super-block, gguf::Q4_K_TYPESIZE = 144 bytes:
//   d      f16 super-block scale for the sub-scales
//   dmin   f16 super-block scale for the sub-mins
//   sc[12] eight 6-bit sub-scales and eight 6-bit sub-mins, packed
//   qs[128] 4-bit quants, low nibble first for each group of 32
// A value is d*sc[sub] * q - dmin*m[sub]; unlike Q4_0 the nibble is unsigned
// and each sub-block carries its own offset.
inline void dequantize_row_q4_K(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* p = src + b * gguf::Q4_K_TYPESIZE;
        const float d    = f16_to_f32((uint16_t)(p[0] | ((uint16_t)p[1] << 8)));
        const float dmin = f16_to_f32((uint16_t)(p[2] | ((uint16_t)p[3] << 8)));
        const uint8_t* sc = p + 4;
        const uint8_t* qs = p + 16;
        float* y = dst + b * gguf::Q4_K_BLOCK;
        int is = 0;
        for (int j = 0; j < (int)gguf::Q4_K_BLOCK; j += 64) {
            uint8_t s, mm;
            get_scale_min_k4(is + 0, sc, &s, &mm);
            const float d1 = d * (float)s, m1 = dmin * (float)mm;
            get_scale_min_k4(is + 1, sc, &s, &mm);
            const float d2 = d * (float)s, m2 = dmin * (float)mm;
            for (int l = 0; l < 32; l++) y[l]      = d1 * (float)(qs[l] & 0xF) - m1;
            for (int l = 0; l < 32; l++) y[l + 32] = d2 * (float)(qs[l] >> 4)  - m2;
            y += 64; qs += 32; is += 2;
        }
    }
}

// Q5_K super-block, gguf::Q5_K_TYPESIZE = 176 bytes:
//   d       f16 super-block scale for the sub-scales
//   dmin    f16 super-block scale for the sub-mins
//   sc[12]  eight 6-bit sub-scales and eight 6-bit sub-mins, packed as in Q4_K
//   qh[32]  the FIFTH bit of every quant, one bit per value
//   qs[128] the low 4 bits
// Q4_K with a fifth bit bolted on: the value is d*sc*(nibble + 16*bit) -
// dmin*m. The bit for a given value lives in qh at a position that advances by
// two per 64-value group, which is what u1/u2 track.
inline void dequantize_row_q5_K(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* p = src + b * gguf::Q5_K_TYPESIZE;
        const float d    = f16_to_f32((uint16_t)(p[0] | ((uint16_t)p[1] << 8)));
        const float dmin = f16_to_f32((uint16_t)(p[2] | ((uint16_t)p[3] << 8)));
        const uint8_t* sc = p + 4;
        const uint8_t* qh = p + 16;
        const uint8_t* ql = p + 48;
        float* y = dst + b * gguf::Q5_K_BLOCK;
        int is = 0;
        uint8_t u1 = 1, u2 = 2;
        for (int j = 0; j < (int)gguf::Q5_K_BLOCK; j += 64) {
            uint8_t s, mm;
            get_scale_min_k4(is + 0, sc, &s, &mm);
            const float d1 = d * (float)s, m1 = dmin * (float)mm;
            get_scale_min_k4(is + 1, sc, &s, &mm);
            const float d2 = d * (float)s, m2 = dmin * (float)mm;
            for (int l = 0; l < 32; l++)
                y[l]      = d1 * (float)((ql[l] & 0xF) + ((qh[l] & u1) ? 16 : 0)) - m1;
            for (int l = 0; l < 32; l++)
                y[l + 32] = d2 * (float)((ql[l] >>  4) + ((qh[l] & u2) ? 16 : 0)) - m2;
            y += 64; ql += 32; is += 2;
            u1 = (uint8_t)(u1 << 2);
            u2 = (uint8_t)(u2 << 2);
        }
    }
}

// Q6_K super-block, gguf::Q6_K_TYPESIZE = 210 bytes:
//   ql[128]  low 4 bits of each quant
//   qh[64]   high 2 bits, packed 4 quants per byte
//   sc[16]   int8 per-16-value scale
//   d        f16 super-block scale
// A quant is (low4 | high2 << 4) - 32, scaled by d * sc[group]. The layout
// walks the block in two halves of 128, which is why the strides below are 64
// for ql, 32 for qh and 8 for sc.
inline void dequantize_row_q6_K(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* p = src + b * gguf::Q6_K_TYPESIZE;
        const uint8_t* ql = p;
        const uint8_t* qh = p + 128;
        const int8_t*  sc = (const int8_t*)(p + 192);
        const float d = f16_to_f32((uint16_t)(p[208] | ((uint16_t)p[209] << 8)));
        float* y = dst + b * gguf::Q6_K_BLOCK;
        for (int n = 0; n < (int)gguf::Q6_K_BLOCK; n += 128) {
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q1 = (int)((ql[l +  0] & 0xF) | (((qh[l] >> 0) & 3) << 4)) - 32;
                const int q2 = (int)((ql[l + 32] & 0xF) | (((qh[l] >> 2) & 3) << 4)) - 32;
                const int q3 = (int)((ql[l +  0] >>  4) | (((qh[l] >> 4) & 3) << 4)) - 32;
                const int q4 = (int)((ql[l + 32] >>  4) | (((qh[l] >> 6) & 3) << 4)) - 32;
                y[l +  0] = d * (float)sc[is + 0] * (float)q1;
                y[l + 32] = d * (float)sc[is + 2] * (float)q2;
                y[l + 64] = d * (float)sc[is + 4] * (float)q3;
                y[l + 96] = d * (float)sc[is + 6] * (float)q4;
            }
            y += 128; ql += 64; qh += 32; sc += 8;
        }
    }
}

} // namespace quant

#pragma once
#include <cstdint>
#include <cstddef>
#include <cmath>
#include <unordered_map>

#include "core/fp16.hpp"
#include "format/gguf.hpp"
#include "quant/k_quants.hpp"

// Q8_0 block quantization kernels, from scratch. A block holds 32 float values
// that are compressed into a 2-byte f16 scale + 32 int8 quantized values
// (gguf::Q8_0_TYPESIZE bytes per block). These kernels are the building blocks
// for both the quantize command (float -> Q8_0) and the dequantize command /
// CPU inference path (Q8_0 -> float).

namespace quant {

inline void quantize_row_q8_0(const float* src, uint8_t* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const float* x = src + b * gguf::Q8_0_BLOCK;
        uint8_t*      y = dst + b * gguf::Q8_0_TYPESIZE;

        float amax = 0.0f;
        for (size_t j = 0; j < gguf::Q8_0_BLOCK; j++)
            amax = std::max(amax, std::fabs(x[j]));

        const float d = amax / 127.0f;
        const uint16_t d16 = f32_to_f16(d);
        y[0] = (uint8_t)(d16 & 0xff);
        y[1] = (uint8_t)(d16 >> 8);

        for (size_t j = 0; j < gguf::Q8_0_BLOCK; j++) {
            float q = (d > 0.0f) ? std::round(x[j] / d) : 0.0f;
            int v = (int)q;
            if (v > 127)  v = 127;
            if (v < -127) v = -127;
            y[2 + j] = (uint8_t)(int8_t)v;
        }
    }
}

inline void dequantize_row_q8_0(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* y = src + b * gguf::Q8_0_TYPESIZE;
        float*         x = dst + b * gguf::Q8_0_BLOCK;

        uint16_t d16 = (uint16_t)(y[0] | ((uint16_t)y[1] << 8));
        const float d = f16_to_f32(d16);
        for (size_t j = 0; j < gguf::Q8_0_BLOCK; j++)
            x[j] = (float)(int8_t)y[2 + j] * d;
    }
}

// Q4_0 block quantization. A block holds 32 floats compressed into a 2-byte f16
// scale + 16 bytes of nibbles (gguf::Q4_0_TYPESIZE = 18 bytes per block). The
// scale is d = amax/7 so the quantized range [-8, 7] maps to [-amax, amax]. Each
// byte holds two values: the low nibble is element j, the high nibble element
// j+16; the stored nibble is unsigned 0..15 where the true value = nibble - 8.
inline void quantize_row_q4_0(const float* src, uint8_t* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const float* x = src + b * gguf::Q4_0_BLOCK;
        uint8_t*      y = dst + b * gguf::Q4_0_TYPESIZE;

        float amax = 0.0f;
        for (size_t j = 0; j < gguf::Q4_0_BLOCK; j++)
            amax = std::max(amax, std::fabs(x[j]));

        const float d = amax / 7.0f;
        const uint16_t d16 = f32_to_f16(d);
        y[0] = (uint8_t)(d16 & 0xff);
        y[1] = (uint8_t)(d16 >> 8);
        const float id = (d > 0.0f) ? (1.0f / d) : 0.0f;

        for (size_t j = 0; j < gguf::Q4_0_BLOCK / 2; j++) {
            int lo = (int)std::round(x[j] * id) + 8;
            int hi = (int)std::round(x[j + gguf::Q4_0_BLOCK / 2] * id) + 8;
            if (lo > 15) lo = 15; if (lo < 0) lo = 0;
            if (hi > 15) hi = 15; if (hi < 0) hi = 0;
            y[2 + j] = (uint8_t)(lo | (hi << 4));
        }
    }
}

inline void dequantize_row_q4_0(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* y = src + b * gguf::Q4_0_TYPESIZE;
        float*         x = dst + b * gguf::Q4_0_BLOCK;

        uint16_t d16 = (uint16_t)(y[0] | ((uint16_t)y[1] << 8));
        const float d = f16_to_f32(d16);
        for (size_t j = 0; j < gguf::Q4_0_BLOCK / 2; j++) {
            uint8_t byte = y[2 + j];
            x[j] = (float)(int)(byte & 0x0F) * d - 8.0f * d;
            x[j + gguf::Q4_0_BLOCK / 2] = (float)(int)(byte >> 4) * d - 8.0f * d;
        }
    }
}

// Q4_1 block: 2-byte f16 scale d, 2-byte f16 min m, then 16 bytes of nibbles
// (gguf::Q4_1_TYPESIZE = 20). Unlike Q4_0 the nibble is unsigned and the block
// carries its own offset, so the value is d*q + m rather than d*(q-8).
inline void quantize_row_q4_1(const float* src, uint8_t* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const float* x = src + b * gguf::Q4_1_BLOCK;
        uint8_t*      y = dst + b * gguf::Q4_1_TYPESIZE;
        float mn = x[0], mx = x[0];
        for (size_t j = 1; j < gguf::Q4_1_BLOCK; j++) {
            mn = std::min(mn, x[j]);
            mx = std::max(mx, x[j]);
        }
        const float d = (mx - mn) / 15.0f;
        const float id = (d > 0.0f) ? (1.0f / d) : 0.0f;
        const uint16_t d16 = f32_to_f16(d), m16 = f32_to_f16(mn);
        y[0] = (uint8_t)(d16 & 0xff); y[1] = (uint8_t)(d16 >> 8);
        y[2] = (uint8_t)(m16 & 0xff); y[3] = (uint8_t)(m16 >> 8);
        for (size_t j = 0; j < gguf::Q4_1_BLOCK / 2; j++) {
            int lo = (int)std::round((x[j] - mn) * id);
            int hi = (int)std::round((x[j + gguf::Q4_1_BLOCK / 2] - mn) * id);
            if (lo > 15) lo = 15; if (lo < 0) lo = 0;
            if (hi > 15) hi = 15; if (hi < 0) hi = 0;
            y[4 + j] = (uint8_t)(lo | (hi << 4));
        }
    }
}

inline void dequantize_row_q4_1(const uint8_t* src, float* dst, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t* y = src + b * gguf::Q4_1_TYPESIZE;
        float*         x = dst + b * gguf::Q4_1_BLOCK;
        const float d = f16_to_f32((uint16_t)(y[0] | ((uint16_t)y[1] << 8)));
        const float m = f16_to_f32((uint16_t)(y[2] | ((uint16_t)y[3] << 8)));
        for (size_t j = 0; j < gguf::Q4_1_BLOCK / 2; j++) {
            const uint8_t byte = y[4 + j];
            x[j]                              = d * (float)(byte & 0x0F) + m;
            x[j + gguf::Q4_1_BLOCK / 2]       = d * (float)(byte >> 4)   + m;
        }
    }
}

// Description of a quantized storage type: fixed block size, bytes per block,
// and block-wise (de)quantize routines. Register each type with the
// quant::Registry so consumers can look a type up by its GGML id.
struct QuantType {
    const char* name = "?";
    size_t block_size = 0;   // values per block
    size_t type_size  = 0;   // bytes per block
    void (*quantize)(const float*, uint8_t*, size_t) = nullptr;
    void (*dequantize)(const uint8_t*, float*, size_t) = nullptr;
};

// Registry of quant types keyed by GGML type id. Populate at startup with
// quant::register_builtins().
class Registry {
public:
    static Registry& instance() {
        static Registry r;
        return r;
    }
    void add(uint32_t ggml_id, const QuantType& t) { types_[ggml_id] = t; }
    const QuantType* get(uint32_t ggml_id) const {
        auto it = types_.find(ggml_id);
        return it == types_.end() ? nullptr : &it->second;
    }
    void clear() { types_.clear(); }

private:
    Registry() = default;
    std::unordered_map<uint32_t, QuantType> types_;
};

// Register the built-in quant types (Q8_0). Safe to call multiple times.
inline void register_builtins() {
    Registry& r = Registry::instance();
    r.clear();
    r.add(gguf::GGML_TYPE_Q8_0,
          { "Q8_0", gguf::Q8_0_BLOCK, gguf::Q8_0_TYPESIZE,
            quantize_row_q8_0, dequantize_row_q8_0 });
    r.add(gguf::GGML_TYPE_Q4_0,
          { "Q4_0", gguf::Q4_0_BLOCK, gguf::Q4_0_TYPESIZE,
            quantize_row_q4_0, dequantize_row_q4_0 });
    r.add(gguf::GGML_TYPE_Q4_1,
          { "Q4_1", gguf::Q4_1_BLOCK, gguf::Q4_1_TYPESIZE,
            quantize_row_q4_1, dequantize_row_q4_1 });
    // Q6_K is read-only: llama.cpp upgrades a few tensors to it inside an
    // otherwise Q4_0 file, so llmx needs to LOAD it, but nothing here produces
    // it and a quantizer would be unused code.
    r.add(gguf::GGML_TYPE_Q4_K,
          { "Q4_K", gguf::Q4_K_BLOCK, gguf::Q4_K_TYPESIZE,
            nullptr, dequantize_row_q4_K });
    r.add(gguf::GGML_TYPE_Q5_K,
          { "Q5_K", gguf::Q5_K_BLOCK, gguf::Q5_K_TYPESIZE,
            nullptr, dequantize_row_q5_K });
    r.add(gguf::GGML_TYPE_Q6_K,
          { "Q6_K", gguf::Q6_K_BLOCK, gguf::Q6_K_TYPESIZE,
            nullptr, dequantize_row_q6_K });
    r.add(gguf::GGML_TYPE_F32,
          { "F32", 0, 4, nullptr, nullptr });
}

} // namespace quant

#pragma once
#include <cstdint>
#include <cstring>
#include <cctype>
#include <string>
#include <vector>
#include <unordered_map>
#include <stdexcept>

#include "format/gguf.hpp"

// GPT-2 style byte-level BPE tokenizer, implemented from scratch.
// Reads tokenizer metadata from a GGUF model:
//   tokenizer.ggml.model        = "gpt2"
//   tokenizer.ggml.tokens       = array<string>   (token id -> byte-mapped token)
//   tokenizer.ggml.token_type   = array<u32>      (per-token type)
//   tokenizer.ggml.merges       = array<string>   ("s1 s2", rank = index)
//   tokenizer.ggml.bos/eos/pad_token_id, add_bos_token

namespace bpe {

// Encode a unicode code point to UTF-8.
inline std::string utf8_encode(uint32_t cp) {
    if (cp < 0x80) return std::string(1, (char)cp);
    if (cp < 0x800) return std::string({ (char)(0xC0 | (cp >> 6)), (char)(0x80 | (cp & 0x3F)) });
    if (cp < 0x10000) return std::string({ (char)(0xE0 | (cp >> 12)), (char)(0x80 | ((cp >> 6) & 0x3F)), (char)(0x80 | (cp & 0x3F)) });
    return std::string({ (char)(0xF0 | (cp >> 18)), (char)(0x80 | ((cp >> 12) & 0x3F)), (char)(0x80 | ((cp >> 6) & 0x3F)), (char)(0x80 | (cp & 0x3F)) });
}

inline size_t utf8_char_len(unsigned char c) {
    if (c >= 0xF0) return 4;
    if (c >= 0xE0) return 3;
    if (c >= 0xC0) return 2;
    return 1;
}

// GPT-2 bytes_to_unicode(): map each byte to a printable unicode code point.
inline std::unordered_map<uint8_t, std::string> build_byte_encoder() {
    std::unordered_map<uint8_t, std::string> m;
    for (int b = 33; b <= 126; b++) m[(uint8_t)b] = utf8_encode((uint32_t)b);
    for (int b = 161; b <= 255; b++)
        if (b != 173) m[(uint8_t)b] = utf8_encode((uint32_t)b);
    int n = 0;
    for (int b = 0; b < 256; b++) {
        // GPT-2 excludes the soft-hyphen byte, mapping it to U+0143 instead.
        bool in = (b >= 33 && b <= 126) || (b >= 161 && b <= 255 && b != 173);
        if (!in) { m[(uint8_t)b] = utf8_encode((uint32_t)(256 + n)); n++; }
    }
    return m;
}

struct SpecialToken {
    std::string text;
    uint32_t id;
};

class Tokenizer {
public:
    std::vector<std::string> vocab;
    std::unordered_map<std::string, uint32_t> token_to_id;
    std::unordered_map<std::string, uint32_t> merge_rank;
    std::unordered_map<uint8_t, std::string> byte_to_char;
    std::unordered_map<std::string, uint8_t> char_to_byte;
    std::vector<SpecialToken> specials; // control / user-defined tokens
    int32_t bos_id = -1;
    int32_t eos_id = -1;
    int32_t pad_id = -1;
    bool add_bos = false;

    Tokenizer(const gguf::GGUFModel& m) {
        byte_to_char = build_byte_encoder();
        for (const auto& kv : byte_to_char) char_to_byte[kv.second] = kv.first;

        // tokens
        const gguf::MetaValue* toks = find_kv(m, "tokenizer.ggml.tokens");
        if (!toks || toks->vtype != gguf::V_ARRAY)
            throw std::runtime_error("tokenizer: missing tokenizer.ggml.tokens");
        vocab.reserve(toks->arr.size());
        for (const auto& e : toks->arr) {
            vocab.push_back(e.s);
            uint32_t id = (uint32_t)vocab.size() - 1;
            token_to_id[e.s] = id;
        }

        // token types (for specials)
        std::vector<uint32_t> types(vocab.size(), 1);
        const gguf::MetaValue* tt = find_kv(m, "tokenizer.ggml.token_type");
        if (tt && tt->vtype == gguf::V_ARRAY) {
            for (size_t i = 0; i < tt->arr.size() && i < types.size(); i++) {
                const auto& e = tt->arr[i];
                if (e.vtype == gguf::V_INT8 || e.vtype == gguf::V_INT16 ||
                    e.vtype == gguf::V_INT32 || e.vtype == gguf::V_INT64)
                    types[i] = (uint32_t)e.i;
                else
                    types[i] = (uint32_t)e.u;
            }
        }

        // merges
        const gguf::MetaValue* mg = find_kv(m, "tokenizer.ggml.merges");
        if (mg && mg->vtype == gguf::V_ARRAY) {
            for (size_t i = 0; i < mg->arr.size(); i++) {
                const std::string& s = mg->arr[i].s;
                size_t sp = s.find(' ');
                std::string merged = (sp == std::string::npos) ? s : (s.substr(0, sp) + s.substr(sp + 1));
                merge_rank[merged] = (uint32_t)i;
            }
        }

        // special tokens: control(3) and user-defined(4)
        for (size_t i = 0; i < vocab.size(); i++) {
            if (types[i] == 3 || types[i] == 4)
                specials.push_back({ vocab[i], (uint32_t)i });
        }

        // ids
        if (const gguf::MetaValue* v = find_kv(m, "tokenizer.ggml.bos_token_id"))
            if (v->vtype == gguf::V_UINT32) bos_id = (int32_t)v->u;
        if (const gguf::MetaValue* v = find_kv(m, "tokenizer.ggml.eos_token_id"))
            if (v->vtype == gguf::V_UINT32) eos_id = (int32_t)v->u;
        if (const gguf::MetaValue* v = find_kv(m, "tokenizer.ggml.padding_token_id"))
            if (v->vtype == gguf::V_UINT32) pad_id = (int32_t)v->u;
        if (const gguf::MetaValue* v = find_kv(m, "tokenizer.ggml.add_bos_token"))
            if (v->vtype == gguf::V_BOOL) add_bos = v->b;
    }

    int32_t token_id(const std::string& s) const {
        auto it = token_to_id.find(s);
        return (it == token_to_id.end()) ? -1 : (int32_t)it->second;
    }

    // --- pre-tokenization (Qwen2/Qwen3 Split regex from tokenizer.json) ---
    //   (?i:'s|'t|'re|'ve|'m|'ll|'d)
    //   | [^\r\n\p{L}\p{N}]?\p{L}+
    //   | \p{N}
    //   |  ?[^\s\p{L}\p{N}]+[\r\n]*
    //   | \s*[\r\n]+
    //   | \s+(?!\S)
    //   | \s+
    // This is NOT the GPT-2 regex. Three differences matter: a leading
    // punctuation or underscore binds to the following word ("_snake", "(x"),
    // digits are emitted one at a time, and a whitespace run ending in newlines
    // stays a single piece. Alternatives are ordered, first match wins.
    static bool is_space(unsigned char c) { return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f'||c=='\v'; }
    static bool is_ascii_letter(unsigned char c) { return (c>='a'&&c<='z')||(c>='A'&&c<='Z'); }
    static bool is_digit(unsigned char c) { return c>='0'&&c<='9'; }
    static bool is_letter(unsigned char c) { return is_ascii_letter(c) || c >= 0x80; }
    static bool is_nl(unsigned char c) { return c=='\r' || c=='\n'; }

    static std::vector<std::string> pretokenize(const std::string& text) {
        std::vector<std::string> out;
        static const char* contractions[] = {"'s","'t","'re","'ve","'m","'ll","'d"};
        size_t i = 0;
        const size_t n = text.size();
        auto emit = [&](size_t b, size_t e) { out.push_back(text.substr(b, e - b)); };
        auto ieq = [](char a, char b) {
            return std::tolower((unsigned char)a) == std::tolower((unsigned char)b);
        };
        while (i < n) {
            // 1. contractions, case-insensitive per the (?i:) group
            if (text[i] == '\'') {
                bool matched = false;
                for (const char* q : contractions) {
                    size_t len = std::strlen(q);
                    if (i + len > n) continue;
                    bool eq = true;
                    for (size_t k = 0; k < len; k++)
                        if (!ieq(text[i + k], q[k])) { eq = false; break; }
                    if (eq) { emit(i, i + len); i += len; matched = true; break; }
                }
                if (matched) continue;
            }
            // 2. optional non-newline non-alnum char, then one or more letters
            { size_t j = i;
              unsigned char c0 = (unsigned char)text[j];
              if (!is_nl(c0) && !is_letter(c0) && !is_digit(c0)) j++;
              size_t k = j;
              while (k < n && is_letter((unsigned char)text[k])) k++;
              if (k > j) { emit(i, k); i = k; continue; } }
            // 3. exactly one digit
            if (is_digit((unsigned char)text[i])) { emit(i, i + 1); i += 1; continue; }
            // 4. optional space, a run of non-space non-alnum, trailing newlines
            { size_t j = i;
              if (text[j] == ' ') j++;
              size_t k = j;
              while (k < n) { unsigned char c = (unsigned char)text[k];
                              if (is_space(c) || is_letter(c) || is_digit(c)) break;
                              k++; }
              if (k > j) { while (k < n && is_nl((unsigned char)text[k])) k++;
                           emit(i, k); i = k; continue; } }
            // 5. whitespace run truncated at its LAST newline, which is what
            //    keeps a blank line a single piece rather than two.
            { size_t k = i;
              while (k < n && is_space((unsigned char)text[k])) k++;
              size_t last_nl = std::string::npos;
              for (size_t q = i; q < k; q++) if (is_nl((unsigned char)text[q])) last_nl = q;
              if (last_nl != std::string::npos) { emit(i, last_nl + 1); i = last_nl + 1; continue; } }
            // 6. whitespace run minus its last char when a non-space follows;
            //    that last space belongs to the next token via rules 2 and 4.
            { size_t k = i;
              while (k < n && is_space((unsigned char)text[k])) k++;
              if (k > i) { size_t e = (k < n) ? k - 1 : k;
                           if (e > i) { emit(i, e); i = e; continue; } } }
            // 7. any remaining whitespace run
            { size_t k = i;
              while (k < n && is_space((unsigned char)text[k])) k++;
              if (k > i) { emit(i, k); i = k; continue; } }
            // safety net: consume one code point
            emit(i, i + utf8_char_len((unsigned char)text[i]));
            i += utf8_char_len((unsigned char)text[i]);
        }
        return out;
    }

    std::string byte_encode(const std::string& raw) const {
        std::string s;
        for (unsigned char b : raw) s += byte_to_char.at(b);
        return s;
    }

    // BPE merge loop over a byte-mapped word.
    std::vector<std::string> bpe(const std::string& word) const {
        std::vector<std::string> sym;
        for (size_t i = 0; i < word.size(); ) {
            size_t l = utf8_char_len((unsigned char)word[i]);
            sym.push_back(word.substr(i, l));
            i += l;
        }
        while (sym.size() > 1) {
            uint32_t best = UINT32_MAX; int best_pos = -1;
            for (size_t i = 0; i + 1 < sym.size(); i++) {
                std::string pair = sym[i] + sym[i + 1];
                auto it = merge_rank.find(pair);
                if (it != merge_rank.end() && it->second < best) { best = it->second; best_pos = (int)i; }
            }
            if (best_pos < 0) break;
            sym[best_pos] += sym[best_pos + 1];
            sym.erase(sym.begin() + best_pos + 1);
        }
        return sym;
    }

    // Encode text, handling special tokens as single ids.
    std::vector<uint32_t> encode(const std::string& text) const {
        std::vector<uint32_t> ids;
        // greedy longest-match split on special tokens
        size_t i = 0; std::string plain;
        auto flush = [&]() {
            if (plain.empty()) return;
            for (const auto& tok : pretokenize(plain)) {
                std::string w = byte_encode(tok);
                for (const auto& sym : bpe(w)) {
                    auto it = token_to_id.find(sym);
                    if (it == token_to_id.end())
                        throw std::runtime_error("tokenizer: symbol not in vocab: " + sym);
                    ids.push_back(it->second);
                }
            }
            plain.clear();
        };
        while (i < text.size()) {
            const SpecialToken* match = nullptr; size_t best_len = 0;
            for (const auto& sp : specials) {
                if (sp.text.size() > best_len && text.compare(i, sp.text.size(), sp.text) == 0) {
                    match = &sp; best_len = sp.text.size();
                }
            }
            if (match) { flush(); ids.push_back(match->id); i += best_len; }
            else { plain += text[i++]; }
        }
        flush();
        return ids;
    }

    std::string decode(const std::vector<uint32_t>& ids) const {
        std::string out;
        for (uint32_t id : ids) {
            const std::string& tok = vocab[id];
            for (size_t i = 0; i < tok.size(); ) {
                size_t l = utf8_char_len((unsigned char)tok[i]);
                std::string ch = tok.substr(i, l);
                auto it = char_to_byte.find(ch);
                if (it != char_to_byte.end()) out += (char)it->second;
                else out += ch;
                i += l;
            }
        }
        return out;
    }

private:
    static const gguf::MetaValue* find_kv(const gguf::GGUFModel& m, const std::string& key) {
        for (const auto& kv : m.kv) if (kv.first == key) return &kv.second;
        return nullptr;
    }
};

} // namespace bpe

#pragma once
#ifndef NOMINMAX
